import { useMemo, useState, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { useDeployStore } from '@/store/deployStore'
import { useDeploySteps } from '@/pages/Deploy/hooks/useDeploySteps'
import { StepCard } from '@/pages/Deploy/components/StepCard'
import { LinkReferenceTable } from '@/pages/Deploy/components/LinkReferenceTable'
import { ChainSelector } from '@/pages/Deploy/components/ChainSelector'
import { ParamInput } from '@/pages/Deploy/components/ParamInput'
import { useDeployContract } from '@/pages/Deploy/hooks/useDeployContract'
import { useConstructorArgs } from '@/pages/Deploy/hooks/useConstructorArgs'
import { useGasEstimateWithBuffer } from '@/pages/Deploy/hooks/useGasEstimateWithBuffer'
import { useSolcMetadata } from '@/pages/Deploy/hooks/useSolcMetadata'
import { useArtifactForStepId, getArtifactNameForStepId } from '@/pages/Deploy/hooks/useDeployedAddressByStepId'
import { replacePlaceholdersInBytecode } from '@/utils/solidity'
import { useRouterLibrariesLink } from '@/pages/Deploy/hooks/useRouterLibrariesLink'
import { ethers } from 'ethers'
import { useWallet } from '@/hooks/useWallet'
import { useWalletStore } from '@/store'
import { formatDecimalUnits } from '@/utils/abiEncodeConstructor'
import type { DeployStep, DeployStepId, ParamHint } from '@/pages/Deploy/types/deploy'
import { DEPLOY_STEP_PUBLIC_IDS, isSupportedDeployStepId } from '@/pages/Deploy/types/deploy'
import { downloadJsonAsFile, currentUtcDateString } from '@/utils/files'
import styles from './DeployTab.module.css'

function artifactNameFor(step: DeployStep): string | undefined {
  return (step as { artifactName?: string }).artifactName
}

export default function DeployTab(): JSX.Element {
  const { t } = useTranslation()
  const steps = useDeploySteps()
  const selectedChainId = useDeployStore((state) => state.selectedChainId)
  void isSupportedDeployStepId // keep TS reference
  void DEPLOY_STEP_PUBLIC_IDS

  const chainLabel =
    selectedChainId === 56
      ? 'BSC Mainnet (56)'
      : selectedChainId === 97
      ? 'BSC Testnet (97)'
      : selectedChainId === 31337
      ? 'Local Anvil Fork (31337)'
      : `Chain ID ${selectedChainId}`

  return (
    <div className={styles.wrapper}>
      <div className={`${styles.intro} bg-white rounded-xl border border-slate-200 p-5 shadow-sm`}>
        <h2 className="text-lg font-bold text-slate-900">
          {t('deploy.deploy.title', '分步部署流程（单步独立执行，默认参数可编辑）')}
        </h2>
        <p className="text-sm leading-relaxed text-slate-600">
          {t(
            'deploy.deploy.subtitle',
            '按顺序 ①→⑮ 部署，依赖未完成时按钮自动禁用；5 个子 Router 地址会自动回填到 DexRouter bytecode 占位符，不需手动复制。'
          )}
        </p>
        <div className={`${styles.chainBadge} gap-2 text-xs font-medium px-3 py-1.5 rounded-lg bg-primary-50 border border-primary-200 text-primary-700`}>
          <span aria-hidden>🔗</span>
          {t(
            'deploy.deploy.chainTip',
            '当前链：{{chain}}。请确认 MetaMask 与 Dashboard 在同一条链上。',
            { chain: chainLabel }
          )}
        </div>
      </div>

      <ChainSelector />

      <ol className={styles.steps}>
        {steps.map((step) => (
          <li key={step.id} className={styles.stepLi}>
            <StepBody step={step} />
          </li>
        ))}
      </ol>

      <div className={`${styles.linkSection} bg-white rounded-xl border border-slate-200 p-5 shadow-sm`}>
        <h3 className="text-sm font-bold text-slate-900 flex items-center gap-2">
          <span aria-hidden>🔗</span>
          子 Router → DexRouter 占位符注入表（自动同步）
        </h3>
        <LinkReferenceTable />
      </div>
    </div>
  )
}

function StepBody({ step }: { readonly step: DeployStep }): JSX.Element {
  const disabledReason = disabledReasonForStep(step)
  const status = step.status ?? 'idle'
  const artifactName = artifactNameFor(step)
  const metadata = useSolcMetadata(artifactName ?? null)
  return (
    <StepCard
      index={step.index}
      title={step.title}
      description={step.description}
      status={status}
      disabledReason={disabledReason}
    >
      {step.id === 'chain-wallet-setup' ? <ChainSetupInline /> : null}
      {step.kind === 'info-table' ? <LinkReferenceTable /> : null}
      {step.kind === 'contract' ? (
        <ContractStepForm step={step} artifactName={artifactName ?? ''} metadata={metadata} />
      ) : null}
      {step.kind === 'bindings-batch' ? <BindingsBatch step={step} /> : null}
      {step.kind === 'write-tx' ? <WriteTxStep step={step} /> : null}
    </StepCard>
  )
}

function disabledReasonForStep(step: DeployStep): string | undefined {
  if (step.status === 'done') return undefined
  if (step.dependsOn && step.dependsOn.length > 0 && step.status === 'blocked') {
    return `依赖未完成：${step.dependsOn.join('、')}`
  }
  return undefined
}

function ChainSetupInline(): JSX.Element {
  return (
    <div className={styles.setupRow}>
      <ChainSelector />
    </div>
  )
}

function ContractStepForm({
  step,
  artifactName,
  metadata,
}: {
  readonly step: DeployStep
  readonly artifactName: string
  readonly metadata: ReturnType<typeof useSolcMetadata>
}): JSX.Element {
  const [deploying, setDeploying] = useState(false)
  const [lastError, setLastError] = useState<string | null>(null)
  const addLog = useDeployStore((state) => state.addLog)
  const drafts = useDeployStore((state) => state.drafts)
  const { deployContract } = useDeployContract()
  const account = useWalletStore((state) => state.account)
  const { chainId } = useWallet()
  const artifact = useArtifactForStepId(step.id)
  const { links } = useRouterLibrariesLink()

  const paramSpecs: readonly ParamHint[] = (step.params as readonly ParamHint[]) ?? []
  const constructorTypes = artifact ? artifact.constructorArgTypes : []
  const args = useConstructorArgs(step.id, paramSpecs, constructorTypes)

  // Build creation bytecode (linked + args concat) for gas estimation
  const { bytecodeForGas, bytecodeWarnings } = useMemo(() => {
    if (!artifact) return { bytecodeForGas: '0x', bytecodeWarnings: [] as readonly string[] }
    const linked = replacePlaceholdersInBytecode(artifact.bytecode, links)
    const body = linked.bytecode + args.encoded.slice(2)
    return { bytecodeForGas: body, bytecodeWarnings: linked.warnings }
  }, [artifact, links, args.encoded])

  const estimate = useGasEstimateWithBuffer({
    enabled: statusReadyOrPending(step.status) && Boolean(account) && artifact != null,
    to: null, // contract creation
    data: bytecodeForGas,
    from: account,
  })

  const handleDeploy = useCallback(async () => {
    setDeploying(true)
    setLastError(null)
    try {
      if (args.errors.length > 0) {
        throw new Error(`Constructor 参数校验未通过：${args.errors.join('；')}`)
      }
      addLog('info', step.id, '开始部署', {
        contract: artifactName,
        values: args.asPrintableReadonly,
        metadata: metadata
          ? {
              compiler: `${metadata.language} ${metadata.version} (viaIR=${metadata.viaIR}, runs=${metadata.runs}, evm=${metadata.evmVersion})`,
              size: `${metadata.expectedDeployedSizeBytes} bytes (${metadata.expectedDeployedSizePctOf24k.toFixed(1)}% of 24KB)`,
            }
          : undefined,
        chainId,
      })
      const result = await deployContract({
        stepId: step.id as DeployStepId,
        paramSpecs,
        rawValues: args.values,
      })
      addLog('success', step.id, '部署成功', {
        address: result.contractAddress,
        txHash: result.txHash,
        blockNumber: result.blockNumber,
        gasUsed: result.gasUsed.toString(),
        size: `${result.deployedSizeBytes} bytes`,
        match: result.metadataHashMatches ? 'MATCHED' : 'NOT_MATCHED',
      })
      downloadJsonAsFile(
        `CFO_${artifactName}_${chainId ?? 'chain'}_${result.contractAddress}_${currentUtcDateString()}_sourcify.json`,
        result.bundle
      )
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e)
      setLastError(msg)
      addLog('error', step.id, '部署失败', { error: msg })
    } finally {
      setDeploying(false)
    }
  }, [addLog, args.errors, args.asPrintableReadonly, args.values, artifactName, chainId, deployContract, metadata, paramSpecs, step.id])

  return (
    <div className={styles.form}>
      {metadata ? (
        <div className={styles.metaBar}>
          <span>
            Compiler: <b>{metadata.version}</b> (viaIR=<b>{String(metadata.viaIR)}</b> / runs=
            <b>{metadata.runs}</b> / evm=<b>{metadata.evmVersion}</b>)
          </span>
          <span className={metadata.expectedDeployedSizePctOf24k > 90 ? styles.warn : ''}>
            Deployed size ≈ {metadata.expectedDeployedSizeBytes} B / 24KB ·{' '}
            {metadata.expectedDeployedSizePctOf24k.toFixed(1)}%
          </span>
          <span>
            Link refs: <b>{metadata.linkReferencesCount}</b>
          </span>
          <span className={metadata.metadataRawPresent ? styles.ok : styles.warn}>
            metadata hash present: {metadata.metadataRawPresent ? 'YES' : 'NO'}
          </span>
        </div>
      ) : null}

      {paramSpecs.length > 0 ? (
        <div className={styles.paramsGrid}>
          {paramSpecs.map((p) => (
            <ParamInput
              key={p.key}
              stepId={step.id}
              spec={p}
              draftValue={drafts.find((d) => d.stepId === step.id && d.key === p.key)?.value}
            />
          ))}
        </div>
      ) : (
        <div className={styles.noArgs}>（本合约无构造参数，constructor() 空）</div>
      )}

      {args.errors.length > 0 ? (
        <ul className={styles.errorBox}>
          {args.errors.map((e, i) => (
            <li key={i}>⚠ {e}</li>
          ))}
        </ul>
      ) : null}
      {bytecodeWarnings.length > 0 ? (
        <ul className={styles.warnBox}>
          {bytecodeWarnings.map((w, i) => (
            <li key={i}>⚠ bytecode: {w}</li>
          ))}
        </ul>
      ) : null}

      <ConstructorArgsPreview encoded={args.encoded} readable={args.asPrintableReadonly} />
      <GasEstimateRow estimate={estimate} onRefresh={estimate.refresh} />

      <div className={styles.actionsRow}>
        <button
          type="button"
          className={`${styles.primary} ${deploying ? styles.busy : ''}`}
          disabled={step.status !== 'ready' || deploying || args.errors.length > 0 || !account}
          onClick={handleDeploy}
        >
          {deploying
            ? '📡 广播中…请在 MetaMask 确认（并等待 2 个确认）'
            : `▶ 部署 ${artifactName}（单步）`}
        </button>
        <span className={styles.smallHint}>
          {account ? '' : '请先连接钱包'}
          {!account ? '' : ` | chainId=${chainId ?? '未连接'}`}
        </span>
      </div>
      {lastError ? <p className={styles.errorInline}>❌ 最近一次报错：{lastError}</p> : null}
    </div>
  )
}

function ConstructorArgsPreview({
  encoded,
  readable,
}: {
  readonly encoded: string
  readonly readable: readonly unknown[]
}): JSX.Element {
  const collapsed = encoded.length > 120 ? `${encoded.slice(0, 66)}…${encoded.slice(-40)}` : encoded
  return (
    <details className={styles.detailsBox}>
      <summary>🔬 构造参数 ABI 预览（点击展开）</summary>
      <pre className={styles.pre}>
{JSON.stringify(readable, null, 2)}
      </pre>
      <div className={styles.codeRow}>
        <span>encoded (末尾追加到 creation bytecode):</span>
        <code>{collapsed}</code>
      </div>
    </details>
  )
}

function GasEstimateRow({
  estimate,
  onRefresh,
}: {
  readonly estimate: ReturnType<typeof useGasEstimateWithBuffer>
  readonly onRefresh: () => void
}): JSX.Element {
  return (
    <div className={styles.gasRow}>
      <span className={styles.gasLabel}>Gas（×1.25 buffer）</span>
      {estimate.loading ? (
        <span className={styles.gasValue}>估算中…</span>
      ) : estimate.error ? (
        <span className={styles.warn}>estimate fail: {truncate(estimate.error, 140)}</span>
      ) : estimate.gasLimit != null ? (
        <>
          <span className={styles.gasValue}>
            {estimate.gasLimit.toString()} units
          </span>
          <span className={styles.gasSub}>
            gasPrice ≈ {estimate.gasPriceGwei?.toFixed(2)} Gwei → cost ≈{' '}
            {estimate.costEth ? formatDecimalUnits(estimate.costEth, 18).slice(0, 10) : '0'} BNB
          </span>
        </>
      ) : (
        <span className={styles.muted}>（钱包未连接或依赖未就绪 → 无法 estimate）</span>
      )}
      <button className={styles.refreshBtn} type="button" onClick={onRefresh}>
        重新估算
      </button>
    </div>
  )
}

function BindingsBatch({ step }: { readonly step: DeployStep }): JSX.Element {
  // For bindings batch step, we provide per-binding mini-cards.
  const bindings = (step as { bindings?: readonly BindingStepJson[] }).bindings ?? []
  return (
    <div className={styles.bindingsGrid}>
      {step.params && (step.params as unknown[]).length > 0 ? (
        <div className={styles.paramsGrid}>
          {(step.params as readonly ParamHint[]).map((p) => (
            <ParamInput
              key={p.key}
              stepId={step.id}
              spec={p}
              draftValue={undefined}
            />
          ))}
        </div>
      ) : null}
      {bindings.map((b) => (
        <BindingMiniCard key={b.id} stepId={step.id} binding={b} _batchStepParams={step.params ?? []} />
      ))}
    </div>
  )
}

interface BindingStepJson {
  readonly id: string
  readonly label: string
  readonly targetStep: string
  readonly targetContract: string
  readonly abiSignature: string
  readonly params?: readonly ParamHint[]
}

function BindingMiniCard({
  stepId,
  binding,
  _batchStepParams,
}: {
  readonly stepId: string
  readonly binding: BindingStepJson
  readonly _batchStepParams: readonly unknown[]
}): JSX.Element {
  const drafts = useDeployStore((state) => state.drafts)
  const addLog = useDeployStore((state) => state.addLog)
  const markBindingCompleted = useDeployStore((state) => state.markBindingCompleted)
  const { signer, provider } = useWallet()
  const account = useWalletStore((state) => state.account)
  const { deployed } = useDeployStore()
  const artifactName = binding.targetContract
  const targetArtifactData = deployed.find((d) => d.contractName === artifactName)
  const [busy, setBusy] = useState(false)
  const [lastError, setLastError] = useState<string | null>(null)

  // Merge parent step params (safeAddress for owner-transfer step) into this binding's drafts.
  const mergedParams: readonly ParamHint[] = useMemo(() => {
    const arr = [...(binding.params ?? [])] as ParamHint[]
    // If binding.params is empty (i.e. uses safeAddress as sole param), and parent step has a safeAddress, add it.
    if (
      arr.length === 0 &&
      stepId === 'transfer-owner-multisig' &&
      binding.abiSignature === 'transferOwnership(address)'
    ) {
      arr.push({
        key: 'newOwner',
        label: `${binding.label} → new owner`,
        description: '从上方 safeAddress 自动带入；需要时可手动改。',
        type: 'address',
        required: true,
        allowZero: false,
        source: 'drafts:transfer-owner-multisig:safeAddress',
      })
    }
    return arr
  }, [binding, stepId])

  const resolvedValues: unknown[] = mergedParams.map((p) => {
    // if source matches drafts:stepId:key → use parent draft value
    if (typeof p.source === 'string' && p.source.startsWith('drafts:')) {
      const parts = p.source.split(':')
      if (parts.length === 3) {
        const [, parentStepId, parentKey] = parts as [string, string, string]
        const parent = drafts.find((d) => d.stepId === parentStepId && d.key === parentKey)
        if (parent != null) return parent.value
      }
    }
    const mine = drafts.find((d) => d.stepId === `${stepId}::${binding.id}` && d.key === p.key)
    if (mine != null) return mine.value
    return (p as { defaultValue?: unknown }).defaultValue
  })

  const canExecute =
    targetArtifactData != null &&
    signer != null &&
    provider != null &&
    mergedParams.every((p, i) => !p.required || isValidRequiredValue(p, resolvedValues[i]))

  // (intentionally unused; reserved for future cross-binding defaults)
  void _batchStepParams

  const execute = useCallback(async () => {
    if (!targetArtifactData || !signer || !provider) return
    setBusy(true)
    setLastError(null)
    try {
      const contract = new ethers.Contract(targetArtifactData.address, targetArtifactData.abi as never, signer)
      const fnName = binding.abiSignature.split('(')[0]
      const fn = (contract as Record<string, (...args: unknown[]) => Promise<ethers.ContractTransaction>>)[fnName]
      if (typeof fn !== 'function') {
        throw new Error(`ABI 里找不到 ${binding.abiSignature}`)
      }
      addLog('info', stepId, `绑定：${binding.label} 广播…`, { target: targetArtifactData.address })
      const tx = await fn(...resolvedValues)
      addLog('pending', stepId, `广播成功：${binding.label}`, { txHash: tx.hash })
      const receipt = await provider.waitForTransaction(tx.hash, 2)
      if (receipt.status === 0) throw new Error(`tx 执行失败 (status=0)`)
      addLog('success', stepId, `✅ 绑定成功：${binding.label}`, {
        txHash: receipt.transactionHash,
        block: receipt.blockNumber,
        gasUsed: receipt.gasUsed.toString(),
      })
      markBindingCompleted(binding.id)
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e)
      setLastError(msg)
      addLog('error', stepId, `❌ 绑定失败：${binding.label}`, { error: msg })
    } finally {
      setBusy(false)
    }
  }, [addLog, binding, markBindingCompleted, provider, resolvedValues, signer, stepId, targetArtifactData])

  return (
    <div className={styles.bindingCard}>
      <div className={styles.bindingHead}>
        <div>
          <div className={styles.bindingName}>{binding.label}</div>
          <div className={styles.bindingSub}>
            target: {binding.targetContract} @{' '}
            <code className={styles.code}>
              {targetArtifactData?.address ?? `（先部署 ${binding.targetStep}）`}
            </code>
          </div>
        </div>
        <button
          type="button"
          className={styles.primary}
          disabled={!canExecute || busy}
          onClick={execute}
        >
          {busy ? '执行中…' : `▶ 执行 ${binding.abiSignature}`}
        </button>
      </div>
      {mergedParams.length > 0 ? (
        <div className={styles.paramsGrid}>
          {mergedParams.map((p, i) => (
            <ParamInput
              key={p.key}
              stepId={`${stepId}::${binding.id}`}
              spec={p}
              draftValue={drafts.find((d) => d.stepId === `${stepId}::${binding.id}` && d.key === p.key)?.value}
              resolvedSourceValue={resolvedValues[i]}
            />
          ))}
        </div>
      ) : null}
      {!account ? <p className={styles.warn}>请先连接钱包</p> : null}
      {lastError ? <p className={styles.errorInline}>❌ {lastError}</p> : null}
    </div>
  )
}

function WriteTxStep({ step }: { readonly step: DeployStep }): JSX.Element {
  const factoryStep = (step.params as readonly ParamHint[] | undefined) ?? []
  const drafts = useDeployStore((state) => state.drafts)
  const addLog = useDeployStore((state) => state.addLog)
  const { signer, provider, chainId } = useWallet()
  const { deployed } = useDeployStore()
  const [busy, setBusy] = useState(false)
  const [lastError, setLastError] = useState<string | null>(null)

  const factoryArtifact = deployed.find((d) => d.contractName === 'MiningPoolFactory')

  // Resolve values matching the spec order. Support explicit draft, then spec.source
  // (e.g. deployed:cfoswap-token) auto-fill from the deployed artifacts list, then defaultValue.
  const resolved = factoryStep.map((spec) => {
    const d = drafts.find((x) => x.stepId === step.id && x.key === spec.key)
    if (d != null) return d.value
    const source = spec.source
    if (source && source.startsWith('deployed:')) {
      const id = source.slice('deployed:'.length)
      const artName = id ? getArtifactNameForStepId(id) : undefined
      const found = artName ? deployed.find((x) => x.contractName === artName) : null
      if (found) return found.address
    }
    return (spec as { defaultValue?: unknown }).defaultValue
  })

  const canRun =
    signer != null &&
    provider != null &&
    factoryArtifact != null &&
    factoryStep.every((p, i) => !p.required || isValidRequiredValue(p, resolved[i]))

  const handleRun = useCallback(async () => {
    if (!factoryArtifact || !signer || !provider) return
    setBusy(true)
    setLastError(null)
    try {
      const contract = new ethers.Contract(factoryArtifact.address, factoryArtifact.abi as never, signer)
      // Match createPoolV2(string name, address rewardToken, uint256 totalReward,
      //   uint256 rewardPerUsd, uint8 mode, address targetPair, uint8 vestingOption,
      //   uint256[8] referralRateBpArr)
      const byKey: Record<string, unknown> = {}
      factoryStep.forEach((s, i) => {
        byKey[s.key] = resolved[i]
      })
      const args = [
        String(byKey.name ?? ''),
        ethers.utils.getAddress(String(byKey.rewardToken)),
        ethers.BigNumber.from(String(byKey.totalReward)),
        ethers.BigNumber.from(String(byKey.rewardPerUsd)),
        Number(byKey.mode),
        ethers.utils.getAddress(String(byKey.pairAddress)),
        Number(byKey.vestingOption),
        (byKey.refRates_8 as readonly number[] ?? []).map((v) => ethers.BigNumber.from(String(v))),
      ]
      addLog('info', step.id, '创建 LP 矿池：开始广播', { args: args.map((a) => (typeof a === 'object' && a && 'toString' in a ? (a as { toString: () => string }).toString() : a)) })
      const record = contract as unknown as Record<string, unknown>
      const createPoolV2Fn = record['createPoolV2'] as undefined | ((...a: unknown[]) => Promise<ethers.ContractTransaction>)
      if (typeof createPoolV2Fn !== 'function') {
        throw new Error('MiningPoolFactory ABI 中没有 createPoolV2 方法（请确认编译的 ABI 是 createPoolV2, createPoolV1 会报此错）')
      }
      const tx = await createPoolV2Fn(...args)
      const receipt = await provider.waitForTransaction(tx.hash, 2)
      if (receipt.status === 0) throw new Error('createPoolV2 reverted')
      // Decode PoolCreated event if present
      let poolAddress: string | null = null
      try {
        const iface = new ethers.utils.Interface(factoryArtifact.abi as never)
        for (const log of receipt.logs) {
          try {
            const parsed = iface.parseLog(log)
            if (parsed.name === 'PoolCreated' || parsed.name === 'Created') {
              const candidate = (parsed.args as Record<string, unknown>).pool as string | undefined
              if (candidate) {
                poolAddress = candidate
                break
              }
            }
          } catch {
            // ignore
          }
        }
      } catch {
        // ignore
      }
      addLog('success', step.id, '✅ 矿池创建完成', {
        txHash: receipt.transactionHash,
        blockNumber: receipt.blockNumber,
        gasUsed: receipt.gasUsed.toString(),
        poolAddress,
      })
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e)
      setLastError(msg)
      addLog('error', step.id, '❌ createPoolV2 失败', { error: msg, chainId })
    } finally {
      setBusy(false)
    }
  }, [addLog, chainId, factoryArtifact, factoryStep, provider, resolved, signer, step.id])

  return (
    <div className={styles.form}>
      {factoryStep.length > 0 ? (
        <div className={styles.paramsGrid}>
          {factoryStep.map((p) => (
            <ParamInput
              key={p.key}
              stepId={step.id}
              spec={p}
              draftValue={drafts.find((d) => d.stepId === step.id && d.key === p.key)?.value}
            />
          ))}
        </div>
      ) : null}
      <div className={styles.actionsRow}>
        <button
          type="button"
          className={styles.primary}
          disabled={!canRun || busy}
          onClick={handleRun}
        >
          {busy ? '⏳ 广播 & 等确认…' : '▶ MiningPoolFactory.createPoolV2'}
        </button>
        <span className={styles.smallHint}>
          {factoryArtifact ? `Factory = ${truncate(factoryArtifact.address, 22)}` : '先部署 MiningPoolFactory (Step 8)'}
        </span>
      </div>
      {lastError ? <p className={styles.errorInline}>❌ {lastError}</p> : null}
    </div>
  )
}

function isValidRequiredValue(spec: ParamHint, value: unknown): boolean {
  if (!spec.required) return true
  if (value === undefined || value === null) return false
  if (typeof value === 'string') return value.length > 0 && (spec.allowZero ? true : value.toLowerCase() !== `0x${'0'.repeat(40)}`)
  if (Array.isArray(value)) return value.length > 0
  if (typeof value === 'number' || typeof value === 'bigint') return true
  return true
}

function statusReadyOrPending(s: unknown): boolean {
  return s === 'ready' || s === 'pending' || s === 'mining'
}

function truncate(s: string, n: number): string {
  if (s.length <= n) return s
  return `${s.slice(0, Math.max(0, n - 3))}…`
}

import { useMemo } from 'react'
import { abiEncodeConstructorArgs } from '@/utils/abiEncodeConstructor.ts'
import type { ParamHint } from '@/pages/Deploy/types/deploy'
import { useWalletStore } from '@/store'
import { useDeployStore } from '@/store/deployStore'
import { useDeployedAddressByStepId } from '@/pages/Deploy/hooks/useDeployedAddressByStepId'
import type { DeployStepId } from '@/pages/Deploy/types/deploy'

export interface ResolvedParam {
  readonly spec: ParamHint
  readonly rawValue: unknown
}

export interface ResolvedConstructorArgs {
  readonly values: readonly unknown[]
  readonly types: readonly string[]
  readonly encoded: string
  readonly asPrintableReadonly: readonly unknown[]
  readonly errors: readonly string[]
  readonly resolved: readonly ResolvedParam[]
}

// Default source resolver for a ParamHint's `source` field.
// Supports:
//   "wallet:account" → current connected wallet address
//   "deployed:<stepId>" → address of the contract deployed by that step; falls back to allowZero=true 0x0 if not deployed + allowZero; otherwise error.
function resolveSourceValue(
  spec: ParamHint,
  accountAddress: string | null,
  getDeployed: (stepId: string) => string | null
): unknown {
  const source = spec.source
  if (!source) return undefined
  if (source === 'wallet:account') {
    return accountAddress
  }
  if (source.startsWith('deployed:')) {
    const id = source.slice('deployed:'.length)
    return getDeployed(id)
  }
  return undefined
}

export function useConstructorArgs(
  stepId: DeployStepId | string,
  paramSpecs: readonly ParamHint[],
  constructorArgTypes: readonly string[]
): ResolvedConstructorArgs {
  const account = useWalletStore((state) => state.account)
  const drafts = useDeployStore((state) => state.drafts)
  const getDeployedGlobal = useDeployedAddressByStepId

  // For every spec:
  //  1) prefer explicit draft value set by user for this stepId+key
  //  2) fallback to resolved source (wallet/deployed:xxx) if resolved to non-null
  //  3) fallback to spec.defaultValue
  //  4) check required / allowZero.
  return useMemo<ResolvedConstructorArgs>(() => {
    const resolved: ResolvedParam[] = []
    const errors: string[] = []

    for (const spec of paramSpecs) {
      let value: unknown = undefined
      const draftEntry = drafts.find((d) => d.stepId === stepId && d.key === spec.key)
      if (draftEntry !== undefined) {
        value = draftEntry.value
      } else {
        const fromSource = resolveSourceValue(spec, account, getDeployedGlobal)
        if (fromSource !== undefined && fromSource !== null) value = fromSource
        else if (Object.prototype.hasOwnProperty.call(spec, 'defaultValue')) value = spec.defaultValue
      }

      // type-specific required + defaults
      if (spec.required) {
        const isEmpty =
          value === undefined ||
          value === null ||
          (typeof value === 'string' && value.length === 0) ||
          (Array.isArray(value) && value.length === 0)
        if (isEmpty) {
          errors.push(`${spec.key}: required but empty`)
        }
      }

      // type-specific checks
      if (spec.type === 'address' && typeof value === 'string') {
        if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
          if (spec.required || (typeof value === 'string' && value.length > 0)) {
            errors.push(`${spec.key}: address must be 42-char 0x-hex`)
          }
        } else if (!spec.allowZero && value.toLowerCase() === `0x${'0'.repeat(40)}`) {
          errors.push(`${spec.key}: zero address not allowed`)
        }
      }
      if (spec.type === 'bp' || spec.type === 'uint') {
        if (spec.min !== undefined && Number(value ?? 0) < spec.min) {
          errors.push(`${spec.key}: must be ≥ ${spec.min}`)
        }
        if (spec.max !== undefined && Number(value ?? 0) > spec.max) {
          errors.push(`${spec.key}: must be ≤ ${spec.max}`)
        }
      }
      if (spec.type === 'rateArray8') {
        const arr = Array.isArray(value) ? (value as readonly unknown[]) : []
        if (arr.length !== 8) errors.push(`${spec.key}: must be exactly 8 levels (L1..L8)`)
        let sum = 0
        for (let i = 0; i < arr.length; i++) {
          const v = Number(arr[i])
          if (!Number.isFinite(v) || v < 0) errors.push(`${spec.key}[${i}]: invalid`)
          sum += v
        }
        if (spec.bpsLimit !== undefined && sum > spec.bpsLimit) {
          errors.push(`${spec.key}: Σbps ${sum} > limit ${spec.bpsLimit}`)
        }
      }
      resolved.push({ spec, rawValue: value })
    }

    const values = resolved.map((r) => r.rawValue)

    let encoded = '0x'
    let printable: readonly unknown[] = []
    // Only encode if errors free AND types lengths match params length
    if (errors.length === 0 && constructorArgTypes.length === values.length) {
      try {
        const res = abiEncodeConstructorArgs(constructorArgTypes, values)
        encoded = res.encoded
        printable = res.valuesAsPrintable
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : String(err)
        errors.push(`Constructor encode failed: ${message}`)
      }
    }
    return {
      values,
      types: constructorArgTypes,
      encoded,
      asPrintableReadonly: printable,
      errors,
      resolved,
    }
  }, [account, constructorArgTypes, drafts, paramSpecs, stepId])
}

import { useEffect, useState } from 'react'
import { ethers } from 'ethers'
import { useWallet } from '@/hooks/useWallet'

interface GasEstimateState {
  readonly loading: boolean
  readonly gasLimit: ethers.BigNumber | null
  readonly gasPriceGwei: number | null
  readonly costEth: ethers.BigNumber | null
  readonly error: string | null
}

const EMPTY_STATE: GasEstimateState = {
  loading: false,
  gasLimit: null,
  gasPriceGwei: null,
  costEth: null,
  error: null,
}

/**
 * Estimate gas for a deployment or a write tx. Buffer = 1.25 × eth_estimateGas result.
 * Recomputes automatically when inputs change (deep equality would be too expensive; we rely on
 * string change for to/data/value hex).
 */
export function useGasEstimateWithBuffer(params: {
  readonly enabled: boolean
  readonly to?: string | null
  readonly data: string
  readonly valueWei?: ethers.BigNumberish
  readonly from?: string | null
  readonly extraBufferMultiplier?: number
}): GasEstimateState & { readonly refresh: () => void } {
  const { provider } = useWallet()
  const [state, setState] = useState<GasEstimateState>(EMPTY_STATE)
  const [nonce, setNonce] = useState(0)

  const multiplier = params.extraBufferMultiplier ?? 1.25
  const key = `${String(params.enabled)}|${params.to ?? '0x'}|${params.data.slice(0, 18)}|${String(params.valueWei ?? 0)}|${params.from ?? ''}|${String(multiplier)}|${String(nonce)}`

  // 未启用或未连接钱包时，在渲染期推导初始状态，避免在 effect 中同步 setState
  const notReady = !params.enabled || !provider

  useEffect(() => {
    if (notReady) return
    let cancelled = false
    setState({ ...EMPTY_STATE, loading: true })
    ;(async () => {
      try {
        const txRequest: ethers.providers.TransactionRequest = {
          from: params.from ?? undefined,
          to: params.to ?? undefined, // deployment tx: to = undefined
          data: params.data,
          value: params.valueWei ?? 0,
        }
        const [estimate, gasPriceNow] = await Promise.all([
          provider.estimateGas(txRequest),
          provider.getGasPrice(),
        ])
        const buffered = estimate.mul(Math.round(multiplier * 100)).div(100)
        const cost = buffered.mul(gasPriceNow)
        if (cancelled) return
        setState({
          loading: false,
          gasLimit: buffered,
          gasPriceGwei: Number(ethers.utils.formatUnits(gasPriceNow, 'gwei')),
          costEth: cost,
          error: null,
        })
      } catch (e: unknown) {
        if (cancelled) return
        const msg = e instanceof Error ? e.message : String(e)
        setState({
          loading: false,
          gasLimit: null,
          gasPriceGwei: null,
          costEth: null,
          error: msg,
        })
      }
    })()
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, provider, notReady])

  return {
    ...(notReady ? EMPTY_STATE : state),
    refresh: () => setNonce((n) => n + 1),
  }
}

import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useWallet } from '@/hooks/useWallet'
import { useWalletStore, useMultisigStore } from '@/store'
import { isValidAddress, copyToClipboard, getExplorerTxUrl, getExplorerAddressUrl, getSafeAppUrl } from '@/utils/address'
import { getChainIconUrl } from '@/utils/chains'
import {
  getSafeContracts,
  SAFE_FACTORY_ABI,
  SAFE_ABI,
  SUPPORTED_CHAINS,
  MAINNET_CHAINS,
  TESTNET_CHAINS
} from '@/config'

function CreateMultisig() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const { isConnected, account, chainId, signer, switchChain, connectWallet } = useWallet()
  const { logs, addLog, clearLogs } = useWalletStore()
  const { addImportedMultisig, setCurrentMultisig } = useMultisigStore()

  const [selectedChain, setSelectedChain] = useState<number>(56)
  const [owners, setOwners] = useState<string[]>(['', ''])
  const [threshold, setThreshold] = useState<number>(2)
  const [isCreating, setIsCreating] = useState(false)
  const [multisigResult, setMultisigResult] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (account && !owners[0]) {
      setOwners([account, ''])
    }
  }, [account])

  useEffect(() => {
    if (chainId && SUPPORTED_CHAINS[chainId]) {
      setSelectedChain(chainId)
    }
  }, [chainId])

  const updateOwner = (idx: number, value: string) => {
    const newOwners = [...owners]
    newOwners[idx] = value.trim()
    setOwners(newOwners)
  }

  const addOwner = () => {
    if (owners.length >= 10) return
    setOwners([...owners, ''])
  }

  const removeOwner = (idx: number) => {
    if (owners.length <= 2) return
    const newOwners = owners.filter((_, i) => i !== idx)
    setOwners(newOwners)
    if (threshold > newOwners.length) {
      setThreshold(newOwners.length)
    }
  }

  const isFormValid = (): boolean => {
    const validOwners = owners.filter((a) => isValidAddress(a))
    if (validOwners.length !== owners.length) return false
    const unique = new Set(owners.map((a) => a.toLowerCase()))
    if (unique.size !== owners.length) return false
    if (threshold < 1 || threshold > owners.length) return false
    return true
  }

  const currentChain = SUPPORTED_CHAINS[selectedChain]
  const safeContracts = getSafeContracts(selectedChain)
  const isZkSync = selectedChain === 324
  const contractSource = isZkSync ? t('create.sourceZkSync') : t('create.sourceStandard')

  const handleCreate = async () => {
    if (!signer || !isConnected) {
      await connectWallet()
      return
    }

    if (chainId !== selectedChain) {
      await switchChain(selectedChain)
      return
    }

    if (!isFormValid()) return

    setIsCreating(true)
    setMultisigResult(null)
    clearLogs()

    try {
      const validOwners = owners.filter((a) => isValidAddress(a))
      addLog('info', t('create.logStart', { network: currentChain?.name }))
      addLog('info', t('create.logOwners', { count: validOwners.length, threshold, total: validOwners.length }))

      addLog('info', t('create.logEncoding'))
      const safeIface = new ethers.utils.Interface(SAFE_ABI)
      const initializer = safeIface.encodeFunctionData('setup', [
        validOwners,
        threshold,
        ethers.constants.AddressZero,
        '0x',
        safeContracts.fallbackHandler,
        ethers.constants.AddressZero,
        0,
        ethers.constants.AddressZero
      ])

      const saltNonce = Date.now()
      addLog('hint', t('create.logSalt', { salt: saltNonce }))

      const factory = new ethers.Contract(safeContracts.proxyFactory, SAFE_FACTORY_ABI, signer)
      addLog('info', t('create.logSending'))

      const tx = await factory.createProxyWithNonce(safeContracts.singleton, initializer, saltNonce, {
        gasLimit: isZkSync ? 2000000 : 500000
      })

      addLog('info', t('create.logTxSent', { hash: tx.hash }))
      const explorerUrl = getExplorerTxUrl(selectedChain, tx.hash)
      addLog('hint', `${t('create.logWaitConfirm')} ${explorerUrl}`)

      addLog('warn', t('create.logWaitConfirm'))
      const receipt = await tx.wait()
      addLog('ok', t('create.logConfirmed', { block: receipt.blockNumber }))

      let multisigAddr: string | null = null
      for (const log of receipt.logs) {
        try {
          const parsed = factory.interface.parseLog(log)
          if (parsed.name === 'ProxyCreation') {
            multisigAddr = parsed.args.proxy
            break
          }
        } catch {}
      }

      if (multisigAddr) {
        addLog('ok', t('create.logSuccess', { address: multisigAddr }))
        setMultisigResult(multisigAddr)
        addImportedMultisig(multisigAddr)
        setCurrentMultisig(multisigAddr)
      } else {
        addLog('warn', t('create.logNoEvent'))
      }
    } catch (error: any) {
      addLog('err', t('create.logError', { error: error.message || error }))
      console.error(error)
    } finally {
      setIsCreating(false)
    }
  }

  const handleCopy = async () => {
    if (multisigResult) {
      await copyToClipboard(multisigResult)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="mb-6">
          <h2 className="text-xl font-bold text-gray-900 mb-2">{t('create.title')}</h2>
          <p className="text-sm text-gray-500">{t('create.subtitle')}</p>
        </div>

        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 mb-6">
          <p className="text-sm text-amber-800 leading-relaxed break-words">
            <strong>⚠️ </strong>
            {t('create.securityWarning')}
          </p>
        </div>

        <div className="mb-6">
          <label className="block text-xs font-bold text-gray-500 mb-3">{t('create.selectNetwork')}</label>

          <div className="mb-4">
            <p className="text-xs font-semibold text-gray-400 mb-2">{t('create.mainnet')}</p>
            <div className="flex gap-2 flex-wrap">
              {MAINNET_CHAINS.map((chain) => (
                <button
                  key={chain.chainId}
                  onClick={() => setSelectedChain(chain.chainId)}
                  className={`flex items-center gap-1.5 px-3 py-2 rounded-xl text-sm font-semibold transition-all ${
                    selectedChain === chain.chainId
                      ? 'bg-blue-50 text-blue-700 border border-blue-200'
                      : 'bg-gray-50 border border-gray-200 text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  <img
                    src={getChainIconUrl(chain.chainId)}
                    alt={chain.shortName}
                    className="w-4 h-4 rounded-full object-contain flex-shrink-0"
                    onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                  />
                  {chain.shortName}
                </button>
              ))}
            </div>
          </div>

          <div>
            <p className="text-xs font-semibold text-gray-400 mb-2">{t('create.testnet')}</p>
            <div className="flex gap-2 flex-wrap">
              {TESTNET_CHAINS.map((chain) => (
                <button
                  key={chain.chainId}
                  onClick={() => setSelectedChain(chain.chainId)}
                  className={`flex items-center gap-1.5 px-3 py-2 rounded-xl text-sm font-semibold transition-all ${
                    selectedChain === chain.chainId
                      ? 'bg-purple-50 text-purple-700 border border-purple-200'
                      : 'bg-gray-50 border border-gray-200 text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  <img
                    src={getChainIconUrl(chain.chainId)}
                    alt={chain.shortName}
                    className="w-4 h-4 rounded-full object-contain flex-shrink-0"
                    onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                  />
                  {chain.shortName}
                </button>
              ))}
            </div>
          </div>
        </div>

        {currentChain && (
          <div className="mb-6 p-4 bg-gray-50 rounded-xl border border-gray-200">
            <div className="flex items-center gap-3 mb-4 flex-wrap">
              <img
                src={getChainIconUrl(selectedChain)}
                alt={currentChain.shortName}
                className="w-8 h-8 rounded-full object-contain bg-white p-1 border border-gray-200 flex-shrink-0"
                onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
              />
              <div className="min-w-0">
                <div className="font-bold text-gray-900">{currentChain.name}</div>
                <div className="text-xs text-gray-500">{t('create.chainId')}: {currentChain.chainId}</div>
              </div>
              {isZkSync && (
                <span className="ml-auto px-2 py-1 bg-amber-100 text-amber-700 text-xs font-semibold rounded-lg whitespace-nowrap">
                  {t('create.specialChain')}
                </span>
              )}
            </div>

            <div className="space-y-3">
              <div className="text-xs font-semibold text-gray-500 mb-2">{t('create.contractSource', { source: contractSource })}</div>

              <div className="bg-white p-3 rounded-lg border border-gray-100">
                <div className="flex items-center justify-between mb-1 gap-2 flex-wrap">
                  <span className="text-xs font-semibold text-gray-500">{t('create.singleton')}</span>
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => copyToClipboard(safeContracts.singleton)}
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold"
                    >
                      {t('common.copy')}
                    </button>
                    <a
                      href={getExplorerAddressUrl(selectedChain, safeContracts.singleton)}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold whitespace-nowrap"
                    >
                      {t('common.viewOnExplorer')} →
                    </a>
                  </div>
                </div>
                <div className="font-mono text-xs text-gray-700 break-all">{safeContracts.singleton}</div>
              </div>

              <div className="bg-white p-3 rounded-lg border border-gray-100">
                <div className="flex items-center justify-between mb-1 gap-2 flex-wrap">
                  <span className="text-xs font-semibold text-gray-500">{t('create.proxyFactory')}</span>
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => copyToClipboard(safeContracts.proxyFactory)}
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold"
                    >
                      {t('common.copy')}
                    </button>
                    <a
                      href={getExplorerAddressUrl(selectedChain, safeContracts.proxyFactory)}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold whitespace-nowrap"
                    >
                      {t('common.viewOnExplorer')} →
                    </a>
                  </div>
                </div>
                <div className="font-mono text-xs text-gray-700 break-all">{safeContracts.proxyFactory}</div>
              </div>

              <div className="bg-white p-3 rounded-lg border border-gray-100">
                <div className="flex items-center justify-between mb-1 gap-2 flex-wrap">
                  <span className="text-xs font-semibold text-gray-500">{t('create.fallbackHandler')}</span>
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => copyToClipboard(safeContracts.fallbackHandler)}
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold"
                    >
                      {t('common.copy')}
                    </button>
                    <a
                      href={getExplorerAddressUrl(selectedChain, safeContracts.fallbackHandler)}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-blue-600 hover:text-blue-700 font-semibold whitespace-nowrap"
                    >
                      {t('common.viewOnExplorer')} →
                    </a>
                  </div>
                </div>
                <div className="font-mono text-xs text-gray-700 break-all">{safeContracts.fallbackHandler}</div>
              </div>
            </div>
          </div>
        )}

        <div className="mb-6">
          <label className="block text-xs font-bold text-gray-500 mb-3">
            {t('create.owners')} <span className="text-gray-400 font-normal">{t('create.ownersHint')}</span>
          </label>
          <div className="space-y-3">
            {owners.map((addr, idx) => {
              const isInvalid = addr.length > 0 && !isValidAddress(addr)
              const isDuplicate =
                addr.length > 0 &&
                owners.filter((a) => a.toLowerCase() === addr.toLowerCase()).length > 1
              return (
                <div key={idx} className="flex items-center gap-2 sm:gap-3">
                  <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-lg bg-gray-50 border border-gray-200 flex items-center justify-center text-xs sm:text-sm font-bold text-gray-500 flex-shrink-0">
                    {idx + 1}
                  </div>
                  <input
                    type="text"
                    value={addr}
                    onChange={(e) => updateOwner(idx, e.target.value)}
                    placeholder={t('create.ownerPlaceholder', { index: idx + 1 })}
                    className={`flex-1 min-w-0 h-10 sm:h-11 px-3 sm:px-4 rounded-xl border text-xs sm:text-sm font-mono bg-gray-50 outline-none focus:border-primary-500 focus:bg-white transition-colors break-all ${
                      isInvalid || isDuplicate ? 'border-red-400 bg-red-50' : 'border-gray-200'
                    }`}
                  />
                  <button
                    onClick={() => removeOwner(idx)}
                    disabled={owners.length <= 2}
                    className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg border border-gray-200 bg-gray-50 text-gray-500 hover:bg-red-50 hover:text-red-600 hover:border-red-200 disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center text-lg flex-shrink-0 transition-colors"
                  >
                    ×
                  </button>
                </div>
              )
            })}
          </div>
          <button
            onClick={addOwner}
            disabled={owners.length >= 10}
            className="mt-3 w-full h-11 rounded-xl border-2 border-dashed border-gray-200 text-gray-500 hover:border-primary-300 hover:text-primary-600 hover:bg-primary-50 disabled:opacity-30 disabled:cursor-not-allowed font-semibold text-sm transition-colors"
          >
            {t('create.addOwner')}
          </button>
        </div>

        <div className="mb-8">
          <label className="block text-xs font-bold text-gray-500 mb-3">{t('create.threshold')}</label>
          <div className="flex items-center gap-2 sm:gap-4 p-3 sm:p-4 bg-gray-50 rounded-xl border border-gray-200 flex-wrap">
            <select
              value={threshold}
              onChange={(e) => setThreshold(parseInt(e.target.value))}
              className="flex-1 min-w-0 h-11 px-3 sm:px-4 rounded-xl border border-gray-200 text-sm sm:text-base font-semibold bg-white outline-none cursor-pointer"
            >
              {owners.map((_, i) => (
                <option key={i + 1} value={i + 1}>
                  {t('create.thresholdOption', { current: i + 1, total: owners.length })}
                </option>
              ))}
            </select>
            <span className="text-xs sm:text-sm text-gray-500 whitespace-nowrap">{t('create.ownersTotal', { count: owners.length })}</span>
          </div>
          <p className="text-xs text-gray-400 mt-2">
            {t('create.thresholdHint')}
          </p>
        </div>

        <button
          onClick={handleCreate}
          disabled={isCreating || !isFormValid()}
          className="w-full h-12 rounded-xl bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none text-white font-bold text-base shadow-lg shadow-primary-500/25 transition-transform hover:scale-[1.02] flex items-center justify-center gap-2"
        >
          {isCreating ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              {t('create.creating')}
            </>
          ) : !isConnected ? (
            t('create.pleaseConnect')
          ) : !isFormValid() ? (
            t('create.fillForm')
          ) : (
            t('create.createBtn')
          )}
        </button>

        {logs.length > 0 && (
          <div className="mt-6 p-4 rounded-xl bg-gray-50 border border-gray-200 font-mono text-xs max-h-72 overflow-y-auto">
            {logs.map((log) => {
              const colorMap: Record<string, string> = {
                ok: 'text-emerald-600',
                err: 'text-red-600',
                warn: 'text-amber-600',
                info: 'text-blue-600',
                hint: 'text-gray-400'
              }
              const prefix: Record<string, string> = {
                ok: '✓ ',
                err: '✗ ',
                warn: '⚠ ',
                info: '• ',
                hint: '  '
              }
              return (
                <div key={log.id} className={`py-1 leading-relaxed break-all ${colorMap[log.type]}`}>
                  {prefix[log.type]}
                  {log.message}
                </div>
              )
            })}
          </div>
        )}

        {multisigResult && (
          <div className="mt-6 p-4 sm:p-5 rounded-2xl bg-emerald-50 border border-emerald-200">
            <h3 className="font-bold text-emerald-800 mb-3 flex items-center gap-2">
              {t('create.resultTitle')}
            </h3>
            <div className="bg-white p-3 sm:p-4 rounded-xl border border-emerald-100 mb-4 flex items-start gap-2 sm:gap-3 flex-wrap sm:flex-nowrap">
              <span className="font-mono text-xs sm:text-sm flex-1 break-all text-gray-800">{multisigResult}</span>
              <button
                onClick={handleCopy}
                className="flex-shrink-0 bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-1.5 rounded-lg text-xs font-bold transition-colors whitespace-nowrap"
              >
                {copied ? t('common.copied') : t('common.copy')}
              </button>
            </div>
            <ul className="text-sm text-emerald-700 space-y-2 list-disc list-inside leading-relaxed break-words">
              <li>{t('create.resultTip1')}</li>
              <li>{t('create.resultTip2')}</li>
              <li>{t('create.resultTip3')}</li>
              <li>{t('create.resultTip4', { symbol: currentChain?.nativeCurrency.symbol || 'BNB' })}</li>
            </ul>
            <div className="flex flex-col sm:flex-row gap-2 mt-4">
              <a
                href={getSafeAppUrl(selectedChain, multisigResult)}
                target="_blank"
                rel="noopener noreferrer"
                className="flex-1 h-11 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold transition-colors flex items-center justify-center text-center px-3"
              >
                {t('create.openSafeOfficial')}
              </a>
              <button
                onClick={() => navigate(`/dashboard/${multisigResult}`)}
                className="flex-1 h-11 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-bold transition-colors"
              >
                {t('create.goToDashboard')}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default CreateMultisig

import { useEffect, useState, useCallback } from 'react'
import { useParams, Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { ethers } from 'ethers'
import { useWalletStore, useMultisigStore } from '@/store/wallet'
import { getSafeInfo, getSafeTokenBalances, getSafePendingTxs, getSafeWebUrl, getSafeServiceUrl, decodeSafeTransaction } from '@/utils/safe'
import { getChainIconUrl } from '@/utils/chains'
import { SUPPORTED_CHAINS } from '@/config'
import { shortenAddress, copyToClipboard, getExplorerAddressUrl } from '@/utils/address'
import type { SafeInfo, TokenBalance, SafePendingTx } from '@/utils/safe'

function Dashboard() {
  const { t } = useTranslation()
  const { address: urlAddress } = useParams<{ address: string }>()
  const { provider, chainId: walletChainId, account } = useWalletStore()
  const { currentMultisig, setCurrentMultisig } = useMultisigStore()

  const [safeAddress, setSafeAddress] = useState<string | null>(null)
  const [safeInfo, setSafeInfo] = useState<SafeInfo | null>(null)
  const [tokenBalances, setTokenBalances] = useState<TokenBalance[]>([])
  const [pendingTxs, setPendingTxs] = useState<SafePendingTx[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [chainError, setChainError] = useState<string | null>(null)
  const [tokenError, setTokenError] = useState<string | null>(null)
  const [pendingError, setPendingError] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    const targetAddress = urlAddress || currentMultisig
    if (targetAddress && ethers.utils.isAddress(targetAddress)) {
      const normalized = targetAddress.toLowerCase()
      setSafeAddress(normalized)
      if (currentMultisig !== normalized) {
        setCurrentMultisig(normalized)
      }
    } else {
      setSafeAddress(null)
    }
  }, [urlAddress, currentMultisig, setCurrentMultisig])

  const loadChainData = useCallback(async () => {
    if (!provider || !safeAddress) return
    setChainError(null)
    try {
      const info = await getSafeInfo(provider, safeAddress)
      setSafeInfo(info)
    } catch (e: any) {
      console.error('Failed to load safe info:', e)
      setChainError(t('dashboard.errorLoadingChain'))
    }
  }, [provider, safeAddress, t])

  const loadTokenBalances = useCallback(async () => {
    if (!safeAddress) return
    setTokenError(null)
    const effectiveChainId = safeInfo?.chainId || walletChainId
    if (!effectiveChainId) return
    const serviceUrl = getSafeServiceUrl(effectiveChainId)
    if (!serviceUrl) {
      setTokenBalances([])
      return
    }
    try {
      const balances = await getSafeTokenBalances(effectiveChainId, safeAddress)
      setTokenBalances(balances)
    } catch (e: any) {
      console.error('Failed to load token balances:', e)
      setTokenError(t('dashboard.errorLoadingTokens'))
    }
  }, [safeAddress, safeInfo?.chainId, walletChainId, t])

  const loadPendingTxs = useCallback(async () => {
    if (!safeAddress) return
    setPendingError(null)
    const effectiveChainId = safeInfo?.chainId || walletChainId
    if (!effectiveChainId) return
    const serviceUrl = getSafeServiceUrl(effectiveChainId)
    if (!serviceUrl) {
      setPendingTxs([])
      return
    }
    try {
      const txs = await getSafePendingTxs(effectiveChainId, safeAddress)
      setPendingTxs(txs)
    } catch (e: any) {
      console.error('Failed to load pending txs:', e)
      setPendingError(t('dashboard.errorLoadingPending'))
    }
  }, [safeAddress, safeInfo?.chainId, walletChainId, t])

  const loadAllData = useCallback(async () => {
    if (!safeAddress || !provider) {
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    try {
      await loadChainData()
      await Promise.all([loadTokenBalances(), loadPendingTxs()])
    } catch (e: any) {
      console.error('Failed to load dashboard data:', e)
      setError(t('dashboard.errorLoading'))
    } finally {
      setLoading(false)
    }
  }, [safeAddress, provider, loadChainData, loadTokenBalances, loadPendingTxs, t])

  useEffect(() => {
    loadAllData()
  }, [loadAllData])

  const handleCopy = async () => {
    if (!safeAddress) return
    await copyToClipboard(safeAddress)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const handleRefresh = () => {
    loadAllData()
  }

  const formatBalance = (balance: string, decimals: number = 18): string => {
    try {
      const formatted = ethers.utils.formatUnits(balance, decimals)
      const num = parseFloat(formatted)
      if (num === 0) return '0'
      if (num < 0.0001) return '< 0.0001'
      return num.toLocaleString(undefined, { maximumFractionDigits: 4 })
    } catch {
      return '0'
    }
  }

  if (!safeAddress) {
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 sm:p-12 text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-gray-100 text-gray-400 text-4xl flex items-center justify-center">
          🔍
        </div>
        <h2 className="text-xl font-bold text-gray-900 mb-3">{t('dashboard.noMultisig')}</h2>
        <p className="text-gray-500 mb-8">{t('dashboard.noMultisigDesc')}</p>
        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <Link
            to="/"
            className="bg-white border-2 border-gray-200 hover:border-primary-300 hover:bg-primary-50 text-gray-700 font-bold px-6 py-3 rounded-xl transition-colors"
          >
            {t('dashboard.goHome')}
          </Link>
          <Link
            to="/import"
            className="bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold px-6 py-3 rounded-xl shadow-lg shadow-primary-500/25 transition-transform hover:scale-105"
          >
            {t('dashboard.goImport')}
          </Link>
        </div>
      </div>
    )
  }

  const effectiveChainId = safeInfo?.chainId || walletChainId
  const currentChain = effectiveChainId ? SUPPORTED_CHAINS[effectiveChainId] : null
  const safeWebUrl = currentChain ? getSafeWebUrl(currentChain.chainId, safeAddress) : getSafeWebUrl(1, safeAddress)
  const explorerUrl = currentChain ? getExplorerAddressUrl(currentChain.chainId, safeAddress) : '#'
  const hasService = currentChain ? !!getSafeServiceUrl(currentChain.chainId) : false

  const nativeBalance = safeInfo ? formatBalance(safeInfo.balance, currentChain?.nativeCurrency.decimals || 18) : '0'
  const nativeSymbol = currentChain?.nativeCurrency.symbol || 'ETH'

  const features = [
    {
      icon: '📝',
      title: t('dashboard.featureNewTx'),
      desc: t('dashboard.featureNewTxDesc'),
      href: `/new-transaction/${safeAddress}`,
      external: false,
      color: 'from-primary-500 to-primary-600',
      shadowColor: 'shadow-primary-500/25'
    },
    {
      icon: '📋',
      title: t('dashboard.featureQueue'),
      desc: t('dashboard.featureQueueDesc'),
      href: `/transactions/${safeAddress}`,
      external: false,
      badge: pendingTxs.length > 0 ? pendingTxs.length : null,
      color: 'from-amber-500 to-orange-500',
      shadowColor: 'shadow-amber-500/25'
    },
    {
      icon: '👥',
      title: t('dashboard.featureOwners'),
      desc: t('dashboard.featureOwnersDesc'),
      href: `/owners/${safeAddress}`,
      external: false,
      color: 'from-emerald-500 to-teal-500',
      shadowColor: 'shadow-emerald-500/25'
    },
    {
      icon: '🌐',
      title: t('dashboard.featureOpenSafe'),
      desc: t('dashboard.featureOpenSafeDesc'),
      href: safeWebUrl,
      external: true,
      color: 'from-blue-500 to-indigo-500',
      shadowColor: 'shadow-blue-500/25'
    }
  ]

  const erc20Tokens = tokenBalances.filter(tb => tb.tokenAddress !== null && tb.token !== null)

  const readyToExecute = pendingTxs.filter(tx => {
    if (tx.isExecuted) return false
    return tx.confirmations.length >= (safeInfo?.threshold || 1)
  })

  const needsMySignature = pendingTxs.filter(tx => {
    if (!account || !safeInfo?.owners) return false
    if (tx.isExecuted) return false
    if (tx.confirmations.length >= (safeInfo?.threshold || 1)) return false // 已经满足执行阈值，不需要再签名了
    const isOwner = safeInfo.owners.some(o => o.toLowerCase() === account.toLowerCase())
    const alreadySigned = tx.confirmations.some(c => c.owner.toLowerCase() === account.toLowerCase())
    return isOwner && !alreadySigned
  })

  const getTxStatusBadge = (tx: SafePendingTx) => {
    if (tx.isExecuted) return <span className="px-2 py-0.5 bg-emerald-100 text-emerald-700 text-xs font-bold rounded-lg">✓ {t('dashboard.txExecuted')}</span>
    const signedCount = tx.confirmations.length
    const threshold = safeInfo?.threshold || 1
    if (signedCount >= threshold) {
      return <span className="px-2 py-0.5 bg-green-100 text-green-700 text-xs font-bold rounded-lg animate-pulse">🚀 {t('dashboard.txReadyToExecute')}</span>
    }
    if (account && safeInfo?.owners) {
      const isOwner = safeInfo.owners.some(o => o.toLowerCase() === account.toLowerCase())
      const alreadySigned = tx.confirmations.some(c => c.owner.toLowerCase() === account.toLowerCase())
      if (isOwner && !alreadySigned) {
        return <span className="px-2 py-0.5 bg-red-100 text-red-700 text-xs font-bold rounded-lg animate-pulse">✍️ {t('dashboard.txNeedsYourSig')}</span>
      }
    }
    return <span className="px-2 py-0.5 bg-gray-100 text-gray-600 text-xs font-bold rounded-lg">⏳ {t('dashboard.txWaiting')}</span>
  }

  const isOwner = (ownerAddr: string): boolean => {
    if (!safeInfo?.owners) return false
    return safeInfo.owners.some(o => o.toLowerCase() === ownerAddr.toLowerCase())
  }

  const getTxDescription = (tx: SafePendingTx): string => {
    const decoded = decodeSafeTransaction(tx.data || '0x', tx.value)
    switch (decoded.type) {
      case 'transfer':
        return t('txs.descTransfer', { address: shortenAddress(tx.to), symbol: nativeSymbol })
      case 'erc20Transfer':
        return t('txs.descErc20Transfer', { address: shortenAddress(decoded.to || tx.to) })
      case 'addOwner':
        return t('txs.descAddOwner', { address: shortenAddress(decoded.owner || '') })
      case 'removeOwner':
        return t('txs.descRemoveOwner', { address: shortenAddress(decoded.owner || '') })
      case 'changeThreshold':
        return t('txs.descChangeThreshold', { threshold: decoded.newThreshold || 0 })
      default:
        return t('txs.descCustom')
    }
  }

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <Link to="/" className="text-sm text-primary-600 hover:text-primary-700 font-semibold mb-2 inline-block">
              {t('common.backHome')}
            </Link>
            <h2 className="text-xl sm:text-2xl font-bold text-gray-900">{t('dashboard.title')}</h2>
          </div>
          <button
            onClick={handleRefresh}
            disabled={loading}
            className="h-10 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            <span className={loading ? 'animate-spin' : ''}>🔄</span>
            {t('dashboard.refresh')}
          </button>
        </div>

        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 p-4 bg-gradient-to-br from-gray-50 to-gray-100 rounded-xl border border-gray-200 mb-6 flex-wrap">
          {currentChain && (
            <img
              src={getChainIconUrl(currentChain.chainId)}
              alt={currentChain.shortName}
              className="w-12 h-12 rounded-full object-contain bg-white p-1.5 border border-gray-200 flex-shrink-0"
              onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
            />
          )}
          <div className="min-w-0 flex-1">
            <div className="font-mono text-sm sm:text-lg text-gray-800 break-all mb-1">{safeAddress}</div>
            <div className="flex items-center gap-3 flex-wrap">
              {currentChain && (
                <span className="text-xs sm:text-sm text-gray-500 flex items-center gap-1">
                  {t('dashboard.currentChain')}: <strong className="text-gray-700">{currentChain.name}</strong>
                  {currentChain.isTestnet && (
                    <span className="ml-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded text-xs font-semibold">
                      {t('dashboard.testnet')}
                    </span>
                  )}
                </span>
              )}
              <span className="text-emerald-600 text-xs sm:text-sm font-semibold flex items-center gap-1">
                ✓ {t('dashboard.imported')}
              </span>
            </div>
          </div>
          <div className="flex gap-2 flex-shrink-0 w-full sm:w-auto">
            <button
              onClick={handleCopy}
              className="flex-1 sm:flex-none h-10 px-4 rounded-xl bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 font-semibold text-sm transition-colors whitespace-nowrap"
            >
              {copied ? t('common.copied') : t('dashboard.copyAddress')}
            </button>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <a
            href={explorerUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 h-11 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold text-sm transition-colors flex items-center justify-center"
          >
            🔍 {t('dashboard.explorer')}
          </a>
          <a
            href={safeWebUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 h-11 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-sm transition-colors flex items-center justify-center px-3 text-center"
          >
            🔗 {t('dashboard.featureOpenSafe')}
          </a>
        </div>

        {/* 当前钱包身份提示 */}
        {account && safeInfo && (
          <div className={`mt-4 p-3 rounded-xl border ${
            isOwner(account) 
              ? 'bg-emerald-50 border-emerald-200' 
              : 'bg-red-50 border-red-200'
          }`}>
            <div className="flex items-center gap-2 flex-wrap">
              <span>{isOwner(account) ? '✅' : '⚠️'}</span>
              <span className={`text-sm font-semibold ${
                isOwner(account) ? 'text-emerald-800' : 'text-red-800'
              }`}>
                {isOwner(account) 
                  ? t('txs.currentIsOwner', { address: shortenAddress(account) })
                  : t('txs.currentNotOwner', { address: shortenAddress(account) })
                }
              </span>
            </div>
          </div>
        )}
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-2xl p-4 sm:p-6">
          <p className="text-red-700 font-semibold mb-2">⚠️ {error}</p>
          <button
            onClick={handleRefresh}
            className="text-sm text-red-600 hover:text-red-700 font-semibold underline"
          >
            {t('dashboard.refresh')}
          </button>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <h3 className="font-bold text-gray-900 mb-4 text-lg">{t('dashboard.overview')}</h3>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="text-gray-400 flex items-center gap-2">
              <span className="animate-spin">⏳</span>
              {t('dashboard.loading')}
            </div>
          </div>
        ) : chainError ? (
          <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center">
            <p className="text-red-700 text-sm mb-2">{chainError}</p>
            <button
              onClick={loadChainData}
              className="text-sm text-red-600 hover:text-red-700 font-semibold underline"
            >
              {t('dashboard.refresh')}
            </button>
          </div>
        ) : safeInfo ? (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
            <div className="p-3 sm:p-4 rounded-xl bg-gradient-to-br from-primary-50 to-primary-100 border border-primary-200">
              <div className="text-xs text-primary-600 font-semibold mb-1">{t('dashboard.threshold')}</div>
              <div className="text-xl sm:text-2xl font-bold text-primary-700">
                {t('dashboard.thresholdValue', { current: safeInfo.threshold, total: safeInfo.owners.length })}
              </div>
            </div>
            <div className="p-3 sm:p-4 rounded-xl bg-gradient-to-br from-emerald-50 to-emerald-100 border border-emerald-200">
              <div className="text-xs text-emerald-600 font-semibold mb-1">{t('dashboard.owners')}</div>
              <div className="text-xl sm:text-2xl font-bold text-emerald-700">{safeInfo.owners.length}</div>
            </div>
            <div className="p-3 sm:p-4 rounded-xl bg-gradient-to-br from-blue-50 to-blue-100 border border-blue-200">
              <div className="text-xs text-blue-600 font-semibold mb-1">{t('dashboard.txNonce')}</div>
              <div className="text-xl sm:text-2xl font-bold text-blue-700">{safeInfo.nonce}</div>
            </div>
            <div className="p-3 sm:p-4 rounded-xl bg-gradient-to-br from-amber-50 to-amber-100 border border-amber-200">
              <div className="text-xs text-amber-600 font-semibold mb-1">{t('dashboard.pendingTxs')}</div>
              <div className="text-xl sm:text-2xl font-bold text-amber-700">
                {pendingError ? '!' : pendingTxs.length}
              </div>
            </div>
          </div>
        ) : null}

        {safeInfo && (
          <div className="mt-4 p-3 sm:p-4 rounded-xl bg-gray-50 border border-gray-200">
            <div className="flex items-center justify-between gap-3 flex-wrap">
              <div className="flex items-center gap-2">
                <span className="text-lg">💰</span>
                <span className="text-sm text-gray-500 font-semibold">{t('dashboard.nativeBalance')}</span>
              </div>
              <div className="font-bold text-gray-900 text-base sm:text-lg">
                {nativeBalance} {nativeSymbol}
              </div>
            </div>
          </div>
        )}
      </div>

      {pendingTxs.length > 0 && safeInfo && (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-bold text-gray-900 text-lg flex items-center gap-2">
              📋 {t('dashboard.pendingTxTitle')}
              <span className="px-2 py-0.5 bg-red-500 text-white text-xs font-bold rounded-full">{pendingTxs.length}</span>
            </h3>
            <Link
              to={`/transactions/${safeAddress}`}
              className="text-sm text-primary-600 hover:text-primary-700 font-semibold"
            >
              {t('dashboard.viewAll')} →
            </Link>
          </div>

          {(needsMySignature.length > 0 || readyToExecute.length > 0) && (
            <div className="flex flex-wrap gap-2 mb-4">
              {needsMySignature.length > 0 && (
                <span className="px-3 py-1.5 bg-red-50 border border-red-200 text-red-700 text-sm font-semibold rounded-xl">
                  ✍️ {t('dashboard.needsYourSig', { count: needsMySignature.length })}
                </span>
              )}
              {readyToExecute.length > 0 && (
                <span className="px-3 py-1.5 bg-green-50 border border-green-200 text-green-700 text-sm font-semibold rounded-xl">
                  🚀 {t('dashboard.readyToExecute', { count: readyToExecute.length })}
                </span>
              )}
            </div>
          )}

          <div className="space-y-3">
            {pendingTxs.slice(0, 5).map((tx) => {
              const signedCount = tx.confirmations.length
              const threshold = safeInfo.threshold
              const progress = Math.min((signedCount / threshold) * 100, 100)
              return (
                <Link
                  key={tx.safeTxHash || `${tx.nonce}-${tx.to}`}
                  to={`/transactions/${safeAddress}`}
                  className="block p-4 rounded-xl border border-gray-200 hover:border-primary-300 hover:bg-primary-50/30 transition-all"
                >
                  <div className="flex items-start justify-between gap-3 mb-2">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="px-2 py-0.5 bg-gray-100 text-gray-600 text-xs font-mono font-bold rounded">
                        #{tx.nonce}
                      </span>
                      {getTxStatusBadge(tx)}
                    </div>
                    <div className="text-xs text-gray-500 font-mono flex-shrink-0">
                      {signedCount}/{threshold} {t('dashboard.signatures')}
                    </div>
                  </div>
                  <p className="text-sm text-gray-800 font-semibold mb-2">{getTxDescription(tx)}</p>
                  <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all ${
                        signedCount >= threshold
                          ? 'bg-gradient-to-r from-green-500 to-emerald-500'
                          : 'bg-gradient-to-r from-primary-500 to-primary-600'
                      }`}
                      style={{ width: `${progress}%` }}
                    />
                  </div>
                </Link>
              )
            })}
          </div>

          {pendingTxs.length > 5 && (
            <div className="mt-4 text-center">
              <Link
                to={`/transactions/${safeAddress}`}
                className="text-sm text-primary-600 hover:text-primary-700 font-semibold"
              >
                {t('dashboard.moreTxs', { count: pendingTxs.length - 5 })} →
              </Link>
            </div>
          )}
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-gray-900 text-lg">{t('dashboard.assets')}</h3>
          {!hasService && !loading && (
            <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded-lg">
              {t('dashboard.serviceUnavailable')}
            </span>
          )}
        </div>

        {tokenError && (
          <div className="bg-orange-50 border border-orange-200 rounded-xl p-3 mb-4">
            <p className="text-orange-700 text-sm">{tokenError}</p>
          </div>
        )}

        {loading ? (
          <div className="py-8 text-center text-gray-400">{t('dashboard.loading')}</div>
        ) : !hasService ? (
          <div className="py-8 text-center">
            <p className="text-gray-400 text-sm">{t('dashboard.serviceUnavailable')}</p>
            <p className="text-gray-400 text-xs mt-1">{nativeBalance} {nativeSymbol}</p>
          </div>
        ) : erc20Tokens.length === 0 ? (
          <div className="py-8 text-center">
            <p className="text-gray-400 text-sm">{t('dashboard.noTokens')}</p>
            <p className="text-gray-500 text-sm mt-2 font-semibold">
              {nativeBalance} {nativeSymbol}
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="flex items-center gap-3 p-3 rounded-xl bg-amber-50 border border-amber-200">
              {currentChain && (
                <img
                  src={getChainIconUrl(currentChain.chainId)}
                  alt={nativeSymbol}
                  className="w-8 h-8 rounded-full object-contain bg-white p-1 border border-amber-200 flex-shrink-0"
                  onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                />
              )}
              <div className="flex-1 min-w-0">
                <div className="font-semibold text-gray-800">{nativeSymbol}</div>
                <div className="text-xs text-gray-500">{currentChain?.nativeCurrency.name || nativeSymbol}</div>
              </div>
              <div className="font-bold text-gray-900 text-right">
                {nativeBalance}
                <div className="text-xs text-gray-500 font-normal">{nativeSymbol}</div>
              </div>
            </div>

            {erc20Tokens.map((tb, idx) => {
              if (!tb.token) return null
              const bal = formatBalance(tb.balance, tb.token.decimals)
              return (
                <div key={idx} className="flex items-center gap-3 p-3 rounded-xl bg-gray-50 border border-gray-200 hover:bg-gray-100 transition-colors">
                  {tb.token.logoUri ? (
                    <img
                      src={tb.token.logoUri}
                      alt={tb.token.symbol}
                      className="w-8 h-8 rounded-full object-contain bg-white p-1 border border-gray-200 flex-shrink-0"
                      onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                    />
                  ) : (
                    <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center text-gray-500 text-xs font-bold flex-shrink-0">
                      {tb.token.symbol.slice(0, 2)}
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <div className="font-semibold text-gray-800 truncate">{tb.token.symbol}</div>
                    <div className="text-xs text-gray-500 truncate">{tb.token.name}</div>
                  </div>
                  <div className="font-bold text-gray-900 text-right truncate">
                    {bal}
                    <div className="text-xs text-gray-500 font-normal truncate">{tb.token.symbol}</div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {safeInfo && (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
          <h3 className="font-bold text-gray-900 mb-4 text-lg">{t('dashboard.ownersList')}</h3>
          <div className="space-y-2">
            {safeInfo.owners.map((owner, idx) => {
              const isYou = account && owner.toLowerCase() === account.toLowerCase()
              return (
                <div
                  key={owner}
                  className={`flex items-center gap-3 p-3 rounded-xl border transition-colors ${
                    isYou
                      ? 'bg-primary-50 border-primary-200'
                      : 'bg-gray-50 border-gray-200 hover:bg-gray-100'
                  }`}
                >
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0 ${
                    isYou ? 'bg-primary-500 text-white' : 'bg-gray-200 text-gray-600'
                  }`}>
                    {idx + 1}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-mono text-sm text-gray-800 break-all">
                      {shortenAddress(owner, 6)}
                    </div>
                  </div>
                  {isYou && (
                    <span className="px-2 py-1 bg-primary-500 text-white text-xs font-bold rounded-lg flex-shrink-0">
                      {t('dashboard.you')}
                    </span>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <h3 className="font-bold text-gray-900 mb-4 text-lg">{t('dashboard.featuresTitle')}</h3>

        {pendingError && (
          <div className="bg-orange-50 border border-orange-200 rounded-xl p-3 mb-4">
            <p className="text-orange-700 text-sm">{pendingError}</p>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4">
          {features.map((f, i) => {
            const cardContent = (
              <>
                <div className={`absolute top-0 right-0 w-24 h-24 bg-gradient-to-br ${f.color} opacity-10 rounded-bl-full -mr-4 -mt-4 group-hover:opacity-20 transition-opacity`} />
                <div className="flex items-start justify-between mb-3 relative z-10">
                  <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${f.color} text-white text-2xl flex items-center justify-center shadow-lg ${f.shadowColor}`}>
                    {f.icon}
                  </div>
                  {f.badge && (
                    <span className="px-2.5 py-1 bg-red-500 text-white text-xs font-bold rounded-full animate-pulse">
                      {f.badge}
                    </span>
                  )}
                </div>
                <div className="font-bold text-gray-800 text-base sm:text-lg mb-1 relative z-10">{f.title}</div>
                <div className="text-xs sm:text-sm text-gray-500 leading-relaxed relative z-10">{f.desc}</div>
                <div className="mt-auto pt-3 text-sm text-primary-600 font-semibold opacity-0 group-hover:opacity-100 transition-opacity relative z-10">
                  →
                </div>
              </>
            )
            const cardClass = "group p-4 sm:p-5 rounded-2xl border border-gray-200 bg-gray-50/50 hover:bg-white hover:border-gray-300 hover:shadow-lg transition-all flex flex-col relative overflow-hidden"
            return f.external ? (
              <a
                key={i}
                href={f.href}
                target="_blank"
                rel="noopener noreferrer"
                className={cardClass}
              >
                {cardContent}
              </a>
            ) : (
              <Link
                key={i}
                to={f.href}
                className={cardClass}
              >
                {cardContent}
              </Link>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export default Dashboard

import { useState, useEffect } from 'react'
import { useNavigate, Link, useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useWallet } from '@/hooks/useWallet'
import { useMultisigStore } from '@/store'
import { isValidAddress, copyToClipboard, getSafeAppUrl } from '@/utils/address'
import { getChainIconUrl } from '@/utils/chains'
import { SUPPORTED_CHAINS } from '@/config'

function ImportMultisig() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const { isConnected, chainId, connectWallet } = useWallet()
  const { importedMultisigs, addImportedMultisig, removeImportedMultisig, setCurrentMultisig } = useMultisigStore()
  const [inputAddress, setInputAddress] = useState('')
  const [error, setError] = useState('')
  const [copied, setCopied] = useState<string | null>(null)
  const [autoImported, setAutoImported] = useState(false)

  // 处理URL参数自动填充和导入
  useEffect(() => {
    const addressParam = searchParams.get('address')
    const redirectParam = searchParams.get('redirect')

    if (addressParam && isValidAddress(addressParam) && !autoImported) {
      setInputAddress(addressParam)
      // 自动导入
      addImportedMultisig(addressParam)
      setCurrentMultisig(addressParam)
      setAutoImported(true)

      // 如果有redirect参数，延迟跳转
      if (redirectParam) {
        setTimeout(() => {
          navigate(redirectParam)
        }, 800)
      }
    }
  }, [searchParams, addImportedMultisig, setCurrentMultisig, navigate, autoImported])

  const handleImport = () => {
    if (!isConnected) {
      connectWallet()
      return
    }
    if (!isValidAddress(inputAddress)) {
      setError(t('import.invalidAddress'))
      return
    }
    addImportedMultisig(inputAddress)
    setCurrentMultisig(inputAddress)
    setInputAddress('')
    setError('')
  }

  const handleCopy = async (addr: string) => {
    await copyToClipboard(addr)
    setCopied(addr)
    setTimeout(() => setCopied(null), 2000)
  }

  const handleManage = (addr: string) => {
    setCurrentMultisig(addr)
    navigate(`/dashboard/${addr}`)
  }

  const defaultChain = chainId ? SUPPORTED_CHAINS[chainId] : SUPPORTED_CHAINS[1]

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="mb-6">
          <Link to="/" className="text-sm text-primary-600 hover:text-primary-700 font-semibold mb-4 inline-block">
            {t('common.backHome')}
          </Link>
          <h2 className="text-xl font-bold text-gray-900 mb-2">{t('import.title')}</h2>
          <p className="text-sm text-gray-500">{t('import.subtitle')}</p>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-500 mb-2">{t('import.addressLabel')}</label>
            <input
              type="text"
              value={inputAddress}
              onChange={(e) => {
                setInputAddress(e.target.value.trim())
                setError('')
              }}
              placeholder={t('import.addressPlaceholder')}
              className={`w-full h-12 px-4 rounded-xl border text-sm font-mono bg-gray-50 outline-none focus:border-primary-500 focus:bg-white transition-colors break-all ${
                error ? 'border-red-400 bg-red-50' : 'border-gray-200'
              }`}
            />
            {error && <p className="text-xs text-red-500 mt-2 break-words">{error}</p>}
          </div>

          <button
            onClick={handleImport}
            className="w-full h-12 rounded-xl bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold text-base shadow-lg shadow-primary-500/25 transition-transform hover:scale-[1.02]"
          >
            {t('import.importBtn')}
          </button>
        </div>

        {importedMultisigs.length > 0 && (
          <div className="mt-8">
            <h3 className="font-bold text-gray-900 mb-4">{t('import.importedTitle')}</h3>
            <div className="space-y-3">
              {importedMultisigs.map((addr) => (
                <div
                  key={addr}
                  className="p-4 rounded-xl border border-gray-200 bg-gray-50/50"
                >
                  <div className="flex items-start gap-3 flex-wrap sm:flex-nowrap">
                    <img
                      src={getChainIconUrl(defaultChain.chainId)}
                      alt={defaultChain.shortName}
                      className="w-8 h-8 rounded-full object-contain bg-white p-1 border border-gray-200 flex-shrink-0 mt-0.5"
                      onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
                    />
                    <div className="flex-1 min-w-0">
                      <div className="font-mono text-sm text-gray-800 break-all mb-2">{addr}</div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <button
                          onClick={() => handleCopy(addr)}
                          className="text-xs px-2 py-1 rounded-lg bg-white border border-gray-200 text-gray-600 hover:bg-gray-50 transition-colors font-semibold"
                        >
                          {copied === addr ? t('common.copied') : t('common.copy')}
                        </button>
                        <a
                          href={getSafeAppUrl(defaultChain.chainId, addr)}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs px-2 py-1 rounded-lg bg-white border border-gray-200 text-blue-600 hover:bg-blue-50 transition-colors font-semibold whitespace-nowrap"
                        >
                          {t('common.viewOnExplorer')}
                        </a>
                        <button
                          onClick={() => handleManage(addr)}
                          className="text-xs px-3 py-1 rounded-lg bg-primary-600 hover:bg-primary-700 text-white font-bold transition-colors whitespace-nowrap"
                        >
                          {t('import.manage')}
                        </button>
                        <button
                          onClick={() => removeImportedMultisig(addr)}
                          className="text-xs px-2 py-1 rounded-lg text-red-500 hover:bg-red-50 transition-colors font-semibold ml-auto"
                        >
                          ✕
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="mt-8 p-4 bg-blue-50 border border-blue-200 rounded-xl">
          <h3 className="font-bold text-blue-800 mb-3">{t('import.tipsTitle')}</h3>
          <ul className="text-sm text-blue-700 space-y-2 list-disc list-inside leading-relaxed break-words">
            <li>{t('import.tip1')}</li>
            <li>{t('import.tip2')}</li>
            <li>{t('import.tip3')}</li>
          </ul>
        </div>
      </div>
    </div>
  )
}

export default ImportMultisig

