import { useState, useEffect, useCallback } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { ethers } from 'ethers'
import { useWalletStore, useMultisigStore } from '@/store'
import {
  getSafeInfo,
  getSafeServiceUrl,
  getTransactionHash,
  signTransactionHash,
  buildERC20TransferData,
  buildEnableOwnerData,
  buildDisableOwnerData,
  buildChangeThresholdData,
  getSafeWebUrl
} from '@/utils/safe'
import { ERC20_ABI, SUPPORTED_CHAINS } from '@/config'
import { getChainIconUrl } from '@/utils/chains'
import { shortenAddress, isAddress, copyToClipboard } from '@/utils/address'
import AddressInput from '@/components/common/AddressInput'
import TokenInput from '@/components/common/TokenInput'
import type { SafeInfo, SafeTransactionData } from '@/utils/safe'

type TxType = 'native' | 'erc20' | 'addOwner' | 'removeOwner' | 'changeThreshold' | 'custom'
type Step = 'selectType' | 'fillForm' | 'preview' | 'signing' | 'success'

interface TokenInfo {
  symbol: string
  decimals: number
  name: string
}

function NewTransaction() {
  const { t } = useTranslation()
  const navigate = useNavigate()
  const { address: urlAddress } = useParams<{ address: string }>()
  const { provider, signer, chainId: walletChainId, account, addLog, clearLogs, logs } = useWalletStore()
  const { currentMultisig } = useMultisigStore()

  const [safeAddress, setSafeAddress] = useState<string | null>(null)
  const [safeInfo, setSafeInfo] = useState<SafeInfo | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const [step, setStep] = useState<Step>('selectType')
  const [txType, setTxType] = useState<TxType | null>(null)

  const [nativeTo, setNativeTo] = useState('')
  const [nativeAmount, setNativeAmount] = useState('')

  const [erc20Contract, setErc20Contract] = useState('')
  const [erc20To, setErc20To] = useState('')
  const [erc20Amount, setErc20Amount] = useState('')
  const [tokenInfo, setTokenInfo] = useState<TokenInfo | null>(null)
  const [loadingToken, setLoadingToken] = useState(false)
  const [erc20Balance, setErc20Balance] = useState<string>('0')

  const [newOwnerAddress, setNewOwnerAddress] = useState('')
  const [newOwnerThreshold, setNewOwnerThreshold] = useState(1)

  const [ownerToRemove, setOwnerToRemove] = useState('')
  const [removeOwnerThreshold, setRemoveOwnerThreshold] = useState(1)

  const [newThreshold, setNewThreshold] = useState(1)

  const [customTo, setCustomTo] = useState('')
  const [customValue, setCustomValue] = useState('0')
  const [customData, setCustomData] = useState('0x')

  const [isSubmitting, setIsSubmitting] = useState(false)
  const [txHash, setTxHash] = useState<string | null>(null)
  const [serviceAvailable, setServiceAvailable] = useState(false)

  useEffect(() => {
    const targetAddress = urlAddress || currentMultisig
    if (targetAddress && ethers.utils.isAddress(targetAddress)) {
      const normalized = targetAddress.toLowerCase()
      setSafeAddress(normalized)
    } else {
      setSafeAddress(null)
    }
  }, [urlAddress, currentMultisig])

  const loadSafeInfo = useCallback(async () => {
    if (!provider || !safeAddress) {
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    try {
      const info = await getSafeInfo(provider, safeAddress)
      setSafeInfo(info)
      const serviceUrl = getSafeServiceUrl(info.chainId)
      setServiceAvailable(!!serviceUrl)
    } catch (e: any) {
      console.error('Failed to load safe info:', e)
      setError(t('newTx.loadError'))
    } finally {
      setLoading(false)
    }
  }, [provider, safeAddress, t])

  useEffect(() => {
    loadSafeInfo()
  }, [loadSafeInfo])

  useEffect(() => {
    if (safeInfo) {
      setNewOwnerThreshold(safeInfo.threshold)
      setRemoveOwnerThreshold(safeInfo.threshold > 1 ? safeInfo.threshold - 1 : 1)
      setNewThreshold(safeInfo.threshold)
    }
  }, [safeInfo])

  const loadTokenInfo = useCallback(async () => {
    if (!provider || !erc20Contract || !isAddress(erc20Contract) || !safeAddress) {
      setTokenInfo(null)
      setErc20Balance('0')
      return
    }
    setLoadingToken(true)
    try {
      const contract = new ethers.Contract(erc20Contract, ERC20_ABI, provider)
      const [symbol, decimals, name, balance] = await Promise.all([
        contract.symbol(),
        contract.decimals(),
        contract.name(),
        contract.balanceOf(safeAddress)
      ])
      setTokenInfo({ symbol, decimals, name })
      setErc20Balance(balance.toString())
    } catch (e) {
      console.error('Failed to load token info:', e)
      setTokenInfo(null)
      setErc20Balance('0')
    } finally {
      setLoadingToken(false)
    }
  }, [provider, erc20Contract, safeAddress])

  useEffect(() => {
    const timer = setTimeout(loadTokenInfo, 500)
    return () => clearTimeout(timer)
  }, [loadTokenInfo])

  const effectiveChainId = safeInfo?.chainId || walletChainId
  const currentChain = effectiveChainId ? SUPPORTED_CHAINS[effectiveChainId] : null
  const nativeSymbol = currentChain?.nativeCurrency.symbol || 'ETH'

  const formatBalance = (balance: string, decimals: number): string => {
    try {
      const formatted = ethers.utils.formatUnits(balance, decimals)
      const num = parseFloat(formatted)
      if (num === 0) return '0'
      if (num < 0.0001) return '< 0.0001'
      return num.toLocaleString(undefined, { maximumFractionDigits: 6 })
    } catch {
      return '0'
    }
  }

  const nativeBalanceFormatted = safeInfo ? formatBalance(safeInfo.balance, currentChain?.nativeCurrency.decimals || 18) : '0'
  const erc20BalanceFormatted = tokenInfo ? formatBalance(erc20Balance, tokenInfo.decimals) : '0'

  const getPrevOwner = (ownerToRemove: string): string => {
    if (!safeInfo) return ethers.constants.AddressZero
    const owners = [...safeInfo.owners].sort((a, b) => a.localeCompare(b))
    const idx = owners.findIndex(o => o.toLowerCase() === ownerToRemove.toLowerCase())
    if (idx === -1) return ethers.constants.AddressZero
    if (idx === 0) return ethers.constants.AddressZero
    return owners[idx - 1]
  }

  const buildTxData = (): Partial<SafeTransactionData> => {
    const base = {
      operation: 0,
      safeTxGas: '0',
      baseGas: '0',
      gasPrice: '0',
      gasToken: ethers.constants.AddressZero,
      refundReceiver: ethers.constants.AddressZero
    }

    switch (txType) {
      case 'native':
        return {
          ...base,
          to: nativeTo,
          value: ethers.utils.parseEther(nativeAmount || '0').toString(),
          data: '0x'
        }
      case 'erc20':
        const tokenAmount = tokenInfo
          ? ethers.utils.parseUnits(erc20Amount || '0', tokenInfo.decimals).toString()
          : '0'
        return {
          ...base,
          to: erc20Contract,
          value: '0',
          data: buildERC20TransferData(erc20Contract, erc20To, tokenAmount)
        }
      case 'addOwner':
        return {
          ...base,
          to: safeAddress!,
          value: '0',
          data: buildEnableOwnerData(newOwnerAddress, newOwnerThreshold)
        }
      case 'removeOwner':
        const prevOwner = getPrevOwner(ownerToRemove)
        return {
          ...base,
          to: safeAddress!,
          value: '0',
          data: buildDisableOwnerData(prevOwner, ownerToRemove, removeOwnerThreshold)
        }
      case 'changeThreshold':
        return {
          ...base,
          to: safeAddress!,
          value: '0',
          data: buildChangeThresholdData(newThreshold)
        }
      case 'custom':
        return {
          ...base,
          to: customTo,
          value: ethers.utils.parseEther(customValue || '0').toString(),
          data: customData || '0x'
        }
      default:
        return base
    }
  }

  const validateForm = (): boolean => {
    if (!safeInfo || !txType || !account) return false

    // 检查当前钱包是否是多签持有人
    const isOwner = safeInfo.owners.some(o => o.toLowerCase() === account.toLowerCase())
    if (!isOwner) return false

    switch (txType) {
      case 'native':
        if (!isAddress(nativeTo)) return false
        if (!nativeAmount || parseFloat(nativeAmount) <= 0) return false
        return true
      case 'erc20':
        if (!isAddress(erc20Contract)) return false
        if (!isAddress(erc20To)) return false
        if (!erc20Amount || parseFloat(erc20Amount) <= 0) return false
        if (!tokenInfo) return false
        return true
      case 'addOwner':
        if (!isAddress(newOwnerAddress)) return false
        if (safeInfo.owners.some(o => o.toLowerCase() === newOwnerAddress.toLowerCase())) return false
        if (newOwnerThreshold < 1 || newOwnerThreshold > safeInfo.owners.length + 1) return false
        return true
      case 'removeOwner':
        if (!isAddress(ownerToRemove)) return false
        if (safeInfo.owners.length <= 1) return false
        if (removeOwnerThreshold < 1 || removeOwnerThreshold > safeInfo.owners.length - 1) return false
        return true
      case 'changeThreshold':
        if (newThreshold < 1 || newThreshold > safeInfo.owners.length) return false
        return true
      case 'custom':
        if (!isAddress(customTo)) return false
        if (!customData || !customData.startsWith('0x')) return false
        return true
      default:
        return false
    }
  }

  const handleSignAndSubmit = async () => {
    if (!signer || !provider || !safeInfo || !safeAddress || !txType) return

    // 提前检查当前钱包是否是多签持有人
    if (account && safeInfo.owners) {
      const isOwner = safeInfo.owners.some(o => o.toLowerCase() === account.toLowerCase())
      if (!isOwner) {
        clearLogs()
        addLog('err', t('newTx.log.notOwnerError', {
          connected: account,
          owners: safeInfo.owners.map(o => shortenAddress(o)).join(', ')
        }))
        return
      }
    }

    setIsSubmitting(true)
    clearLogs()
    setTxHash(null)

    try {
      const txData = buildTxData()
      const nonce = safeInfo.nonce
      const toChecksum = (addr: string): string => {
        if (!addr || addr === ethers.constants.AddressZero) return ethers.constants.AddressZero
        return ethers.utils.getAddress(addr)
      }
      const fullTxData: SafeTransactionData = {
        to: toChecksum(txData.to!),
        value: txData.value!,
        data: txData.data!,
        operation: txData.operation!,
        safeTxGas: txData.safeTxGas!,
        baseGas: txData.baseGas!,
        gasPrice: txData.gasPrice!,
        gasToken: toChecksum(txData.gasToken!),
        refundReceiver: toChecksum(txData.refundReceiver!),
        nonce
      }

      addLog('info', t('newTx.log.generatingHash'))
      // 关键：必须使用链上合约返回的hash作为权威safeTxHash
      const safeTxHash = await getTransactionHash(provider, safeAddress, fullTxData)
      addLog('ok', t('newTx.log.hashGenerated', { hash: shortenAddress(safeTxHash) }))

      addLog('info', t('newTx.log.signing'))
      const signResult = await signTransactionHash(signer, safeInfo.chainId, safeAddress, fullTxData)
      const sig = signResult.signature

      addLog('info', t('newTx.log.verifyingSig'))
      const signerMatch = signResult.recoveredAddress.toLowerCase() === signResult.expectedSigner.toLowerCase()
      const hashMatch = safeTxHash.toLowerCase() === signResult.txHash.toLowerCase()

      if (!signerMatch) {
        addLog('err', t('newTx.log.sigVerifyFailed', { recovered: signResult.recoveredAddress, expected: signResult.expectedSigner }))
        throw new Error(t('newTx.log.sigVerifyFailedShort'))
      }
      if (!hashMatch) {
        // hash不匹配是严重错误，说明签名数据构造有问题
        addLog('err', t('newTx.log.hashMismatch', { onChain: shortenAddress(safeTxHash), local: shortenAddress(signResult.txHash) }))
        throw new Error(t('newTx.log.hashMismatchShort'))
      }

      setTxHash(safeTxHash)
      addLog('ok', t('newTx.log.signed'))
      addLog('ok', t('newTx.log.sigVerified', { signer: shortenAddress(signResult.recoveredAddress) }))

      const serviceUrl = getSafeServiceUrl(safeInfo.chainId)
      if (serviceUrl) {
        addLog('info', t('newTx.log.submittingToService'))
        const checksumSafeAddress = toChecksum(safeAddress)
        const checksumSender = toChecksum(account!)
        const response = await fetch(`${serviceUrl}/api/v1/safes/${checksumSafeAddress}/multisig-transactions/`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            to: fullTxData.to,
            value: fullTxData.value.toString(),
            data: fullTxData.data,
            operation: fullTxData.operation,
            safeTxGas: fullTxData.safeTxGas.toString(),
            baseGas: fullTxData.baseGas.toString(),
            gasPrice: fullTxData.gasPrice.toString(),
            gasToken: fullTxData.gasToken,
            refundReceiver: fullTxData.refundReceiver,
            nonce: fullTxData.nonce,
            safeTxHash: safeTxHash,
            contractTransactionHash: safeTxHash,
            sender: checksumSender,
            signature: sig,
            origin: 'CfoLock'
          })
        })

        if (response.ok) {
          addLog('ok', t('newTx.log.submitSuccess'))
          setStep('success')
        } else {
          const errText = await response.text()
          addLog('err', t('newTx.log.submitFailed', { error: errText }))
        }
      } else {
        addLog('warn', t('newTx.log.noService'))
        setStep('success')
      }
    } catch (e: any) {
      addLog('err', t('newTx.log.error', { error: e.message || e }))
      console.error(e)
    } finally {
      setIsSubmitting(false)
    }
  }

