              setNativeAmount('')
              setErc20Contract('')
              setErc20To('')
              setErc20Amount('')
              setTokenInfo(null)
              setNewOwnerAddress('')
              setOwnerToRemove('')
              setCustomTo('')
              setCustomValue('0')
              setCustomData('0x')
              setTxHash(null)
            }}
            className="flex-1 h-11 rounded-xl border-2 border-gray-200 text-gray-700 font-bold hover:bg-gray-50 transition-colors"
          >
            {t('newTx.success.newTx')}
          </button>
          <button
            onClick={() => navigate(`/transactions/${safeAddress}`)}
            className="flex-1 h-11 rounded-xl bg-gradient-to-r from-primary-500 to-primary-600 text-white font-bold shadow-lg shadow-primary-500/25 transition-transform hover:scale-[1.02]"
          >
            {t('newTx.success.goToQueue')}
          </button>
        </div>
        <a
          href={safeWebUrl + '/transactions/queue'}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-2 text-sm text-primary-600 font-semibold hover:text-primary-700"
        >
          🔗 {t('newTx.success.openSafe')} →
        </a>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 text-center">
        <div className="text-gray-400 flex items-center justify-center gap-2">
          <span className="animate-spin">⏳</span>
          {t('newTx.loading')}
        </div>
      </div>
    )
  }

  if (error || !safeAddress || !safeInfo) {
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-red-100 text-red-400 text-4xl flex items-center justify-center">
          ⚠️
        </div>
        <h2 className="text-xl font-bold text-gray-900 mb-3">{t('newTx.noMultisig')}</h2>
        <p className="text-gray-500 mb-8">{error || t('newTx.noMultisigDesc')}</p>
        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <button
            onClick={() => navigate('/')}
            className="bg-white border-2 border-gray-200 hover:border-primary-300 hover:bg-primary-50 text-gray-700 font-bold px-6 py-3 rounded-xl transition-colors"
          >
            {t('common.backHome')}
          </button>
          <button
            onClick={() => navigate('/import')}
            className="bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold px-6 py-3 rounded-xl shadow-lg shadow-primary-500/25 transition-transform hover:scale-105"
          >
            {t('nav.import')}
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="mb-6">
          <button
            onClick={() => {
              if (step === 'fillForm') setStep('selectType')
              else if (step === 'preview') setStep('fillForm')
              else navigate(`/dashboard/${safeAddress}`)
            }}
            className="text-sm text-primary-600 hover:text-primary-700 font-semibold mb-2"
          >
            ← {step === 'selectType' ? t('common.backToDashboard') : t('common.cancel')}
          </button>
          <h2 className="text-xl font-bold text-gray-900 mb-2">{t('newTx.title')}</h2>
          <p className="text-sm text-gray-500">{t('newTx.subtitle')}</p>
        </div>

        <div className="flex items-center gap-4 p-4 bg-gradient-to-br from-gray-50 to-gray-100 rounded-xl border border-gray-200 mb-4 flex-wrap">
          {currentChain && (
            <img
              src={getChainIconUrl(currentChain.chainId)}
              alt={currentChain.shortName}
              className="w-10 h-10 rounded-full object-contain bg-white p-1 border border-gray-200 flex-shrink-0"
              onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
            />
          )}
          <div className="min-w-0 flex-1">
            <div className="font-mono text-sm text-gray-800 break-all">{shortenAddress(safeAddress, 6)}</div>
            <div className="text-xs text-gray-500">
              {currentChain?.name} · {t('newTx.threshold')}: {safeInfo.threshold}/{safeInfo.owners.length} · {t('dashboard.txNonce')}: {safeInfo.nonce}
            </div>
          </div>
        </div>

        {/* 当前钱包不是持有人时提前显示警告 */}
        {account && safeInfo?.owners && !safeInfo.owners.some(o => o.toLowerCase() === account.toLowerCase()) && (
          <div className="mb-6 bg-red-50 border-2 border-red-200 rounded-xl p-4">
            <p className="text-sm text-red-800 font-bold flex items-center gap-2 mb-2">
              ⚠️ {t('newTx.notOwnerWarning.title')}
            </p>
            <p className="text-xs text-red-700 leading-relaxed">
              {t('newTx.notOwnerWarning.desc', {
                connected: shortenAddress(account),
                owners: safeInfo.owners.map(o => shortenAddress(o)).join(', ')
              })}
            </p>
          </div>
        )}

        <div className="flex items-center justify-center mb-8">
          {(['selectType', 'fillForm', 'preview', 'signing', 'success'] as Step[]).map((s, idx) => {
            const stepLabels: Record<Step, string> = {
              selectType: t('newTx.steps.select'),
              fillForm: t('newTx.steps.fill'),
              preview: t('newTx.steps.preview'),
              signing: t('newTx.steps.sign'),
              success: t('newTx.steps.done')
            }
            const stepNums: Record<Step, number> = { selectType: 1, fillForm: 2, preview: 3, signing: 4, success: 5 }
            const currentIdx = (['selectType', 'fillForm', 'preview', 'signing', 'success'] as Step[]).indexOf(step)
            const isActive = idx <= currentIdx
            const isCurrent = idx === currentIdx
            return (
              <div key={s} className="flex items-center">
                <div className="flex flex-col items-center">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
                    isActive
                      ? isCurrent
                        ? 'bg-primary-500 text-white'
                        : 'bg-primary-100 text-primary-600'
                      : 'bg-gray-100 text-gray-400'
                  }`}>
                    {isActive && idx < currentIdx ? '✓' : stepNums[s]}
                  </div>
                  <span className={`text-xs mt-1 font-medium ${isActive ? 'text-gray-700' : 'text-gray-400'}`}>
                    {stepLabels[s]}
                  </span>
                </div>
                {idx < 4 && (
                  <div className={`w-8 sm:w-16 h-0.5 mx-1 mb-5 transition-colors ${
                    idx < currentIdx ? 'bg-primary-500' : 'bg-gray-200'
                  }`} />
                )}
              </div>
            )
          })}
        </div>

        {step === 'selectType' && renderTypeSelection()}
        {step === 'fillForm' && txType && (
          <div className="space-y-6">
            {renderForm()}
            <div className="flex gap-3">
              <button
                onClick={() => setStep('selectType')}
                className="flex-1 h-12 rounded-xl border-2 border-gray-200 text-gray-700 font-bold hover:bg-gray-50 transition-colors"
              >
                {t('common.cancel')}
              </button>
              <button
                onClick={() => setStep('preview')}
                disabled={!validateForm()}
                className="flex-1 h-12 rounded-xl bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold shadow-lg shadow-primary-500/25 transition-transform hover:scale-[1.02] disabled:transform-none"
              >
                {t('newTx.previewBtn')}
              </button>
            </div>
          </div>
        )}
        {step === 'preview' && (
          <div className="space-y-6">
            {renderPreview()}
            <div className="flex gap-3">
              <button
                onClick={() => setStep('fillForm')}
                className="flex-1 h-12 rounded-xl border-2 border-gray-200 text-gray-700 font-bold hover:bg-gray-50 transition-colors"
              >
                {t('common.cancel')}
              </button>
              <button
                onClick={handleSignAndSubmit}
                disabled={isSubmitting}
                className="flex-1 h-12 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-400 hover:to-teal-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold shadow-lg shadow-emerald-500/25 transition-transform hover:scale-[1.02] disabled:transform-none flex items-center justify-center gap-2"
              >
                {isSubmitting ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    {t('newTx.signing')}
                  </>
                ) : (
                  <>✍️ {t('newTx.signAndSubmit')}</>
                )}
              </button>
            </div>
            {logs.length > 0 && (
              <div className="p-4 rounded-xl bg-gray-50 border border-gray-200 font-mono text-xs max-h-48 overflow-y-auto">
                {logs.map((log) => {
                  const colorMap: Record<string, string> = {
                    ok: 'text-emerald-600',
                    err: 'text-red-600',
                    warn: 'text-amber-600',
                    info: 'text-blue-600',
                    hint: 'text-gray-400'
                  }
                  const prefix: Record<string, string> = {
                    ok: '✓ ',
                    err: '✗ ',
                    warn: '⚠ ',
                    info: '• ',
                    hint: '  '
                  }
                  return (
                    <div key={log.id} className={`py-1 leading-relaxed break-all ${colorMap[log.type]}`}>
                      {prefix[log.type]}
                      {log.message}
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        )}
        {step === 'success' && renderSuccess()}
      </div>
    </div>
  )
}

export default NewTransaction

import { useEffect, useState, useCallback } from 'react'
import { Link, useParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useWalletStore, useMultisigStore } from '@/store/wallet'
import { getSafeInfo, getSafeWebUrl } from '@/utils/safe'
import { SUPPORTED_CHAINS } from '@/config'
import { shortenAddress, isAddress, copyToClipboard, getExplorerAddressUrl } from '@/utils/address'
import { getChainIconUrl } from '@/utils/chains'
import type { SafeInfo } from '@/utils/safe'

function Owners() {
  const { t } = useTranslation()
  const { address: urlAddress } = useParams<{ address: string }>()
  const { provider, chainId: walletChainId, account } = useWalletStore()
  const { currentMultisig, setCurrentMultisig } = useMultisigStore()

  const [safeAddress, setSafeAddress] = useState<string | null>(null)
  const [safeInfo, setSafeInfo] = useState<SafeInfo | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [copiedAddress, setCopiedAddress] = useState<string | null>(null)

  useEffect(() => {
    const targetAddress = urlAddress || currentMultisig
    if (targetAddress && isAddress(targetAddress)) {
      const normalized = targetAddress.toLowerCase()
      setSafeAddress(normalized)
      if (currentMultisig !== normalized) {
        setCurrentMultisig(normalized)
      }
    } else {
      setSafeAddress(null)
    }
  }, [urlAddress, currentMultisig, setCurrentMultisig])

  const loadSafeInfo = useCallback(async () => {
    if (!provider || !safeAddress) {
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    try {
      const info = await getSafeInfo(provider, safeAddress)
      setSafeInfo(info)
    } catch (e: any) {
      console.error('Failed to load safe info:', e)
      setError(t('owners.errorLoading'))
    } finally {
      setLoading(false)
    }
  }, [provider, safeAddress, t])

  useEffect(() => {
    loadSafeInfo()
  }, [loadSafeInfo])

  const handleCopy = async (address: string) => {
    await copyToClipboard(address)
    setCopiedAddress(address)
    setTimeout(() => setCopiedAddress(null), 2000)
  }

  const isOwner = (owner: string): boolean => {
    if (!account) return false
    return owner.toLowerCase() === account.toLowerCase()
  }

  const currentUserIsOwner = (): boolean => {
    if (!safeInfo || !account) return false
    return safeInfo.owners.some(owner => owner.toLowerCase() === account.toLowerCase())
  }

  if (!safeAddress) {
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 sm:p-12 text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-gray-100 text-gray-400 text-4xl flex items-center justify-center">
          🔍
        </div>
        <h2 className="text-xl font-bold text-gray-900 mb-3">{t('owners.noMultisig')}</h2>
        <p className="text-gray-500 mb-8">{t('owners.noMultisigDesc')}</p>
        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <Link
            to="/"
            className="bg-white border-2 border-gray-200 hover:border-primary-300 hover:bg-primary-50 text-gray-700 font-bold px-6 py-3 rounded-xl transition-colors"
          >
            {t('common.backHome')}
          </Link>
          <Link
            to="/import"
            className="bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold px-6 py-3 rounded-xl shadow-lg shadow-primary-500/25 transition-transform hover:scale-105"
          >
            {t('owners.goImport')}
          </Link>
        </div>
      </div>
    )
  }

  const effectiveChainId = safeInfo?.chainId || walletChainId
  const currentChain = effectiveChainId ? SUPPORTED_CHAINS[effectiveChainId] : null
  const safeWebUrl = currentChain ? getSafeWebUrl(currentChain.chainId, safeAddress) : getSafeWebUrl(1, safeAddress)

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <Link to={`/dashboard/${safeAddress}`} className="text-sm text-primary-600 hover:text-primary-700 font-semibold mb-2 inline-block">
              ← {t('common.backToDashboard')}
            </Link>
            <h2 className="text-xl sm:text-2xl font-bold text-gray-900">{t('owners.title')}</h2>
          </div>
          <div className="flex gap-2">
            <button
              onClick={loadSafeInfo}
              disabled={loading}
              className="h-10 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
            >
              <span className={loading ? 'animate-spin' : ''}>🔄</span>
              {t('owners.refresh')}
            </button>
            {safeWebUrl && (
              <a
                href={`${safeWebUrl}/settings/owners`}
                target="_blank"
                rel="noopener noreferrer"
                className="h-10 px-4 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-sm transition-colors flex items-center justify-center"
              >
                🔗 {t('owners.openSafeOfficial')}
              </a>
            )}
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 p-4 bg-gradient-to-br from-gray-50 to-gray-100 rounded-xl border border-gray-200 mb-6 flex-wrap">
          {currentChain && (
            <img
              src={getChainIconUrl(currentChain.chainId)}
              alt={currentChain.shortName}
              className="w-12 h-12 rounded-full object-contain bg-white p-1.5 border border-gray-200 flex-shrink-0"
              onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
            />
          )}
          <div className="min-w-0 flex-1">
            <div className="font-mono text-sm sm:text-lg text-gray-800 break-all mb-1">{safeAddress}</div>
            <div className="flex items-center gap-3 flex-wrap">
              {currentChain && (
                <span className="text-xs sm:text-sm text-gray-500 flex items-center gap-1">
                  {t('owners.currentChain')}: <strong className="text-gray-700">{currentChain.name}</strong>
                  {currentChain.isTestnet && (
                    <span className="ml-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded text-xs font-semibold">
                      {t('owners.testnet')}
                    </span>
                  )}
                </span>
              )}
            </div>
          </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-2xl p-4 sm:p-6">
          <p className="text-red-700 font-semibold mb-2">⚠️ {error}</p>
          <button
            onClick={loadSafeInfo}
            className="text-sm text-red-600 hover:text-red-700 font-semibold underline"
          >
            {t('owners.refresh')}
          </button>
        </div>
      )}

      {loading ? (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 sm:p-12">
          <div className="flex items-center justify-center py-12">
            <div className="text-gray-400 flex items-center gap-2">
              <span className="animate-spin">⏳</span>
              {t('owners.loading')}
            </div>
          </div>
        </div>
      ) : safeInfo ? (
        <>
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
              <h3 className="font-bold text-gray-900 text-lg">{t('owners.thresholdInfo')}</h3>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
              <div className="p-4 sm:p-6 rounded-2xl bg-gradient-to-br from-emerald-50 to-emerald-100 border border-emerald-200">
                <div className="text-xs text-emerald-600 font-semibold mb-2">{t('owners.threshold')}</div>
                <div className="text-3xl sm:text-4xl font-bold text-emerald-700">
                  {safeInfo.threshold}/{safeInfo.owners.length}
                </div>
                <p className="text-sm text-emerald-600 mt-2">
                  {t('owners.thresholdDesc', { current: safeInfo.threshold, total: safeInfo.owners.length })}
                </p>
              </div>
              <div className="p-4 sm:p-6 rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100 border border-blue-200">
                <div className="text-xs text-blue-600 font-semibold mb-2">{t('owners.ownersCount')}</div>
                <div className="text-3xl sm:text-4xl font-bold text-blue-700">
                  {safeInfo.owners.length}
                </div>
                <p className="text-sm text-blue-600 mt-2">
                  {t('owners.ownersCountDesc', { count: safeInfo.owners.length })}
                </p>
              </div>
            </div>

            {!currentUserIsOwner() && account && (
              <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 mb-6">
                <p className="text-amber-700 font-semibold text-sm">
                  ⚠️ {t('owners.notOwnerWarning')}
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-3">
              <Link
                to={currentUserIsOwner() ? "/new-transaction?action=add-owner" : "#"}
                onClick={(e) => {
                  if (!currentUserIsOwner()) {
                    e.preventDefault()
                  }
                }}
                className={`flex-1 h-12 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${
                  currentUserIsOwner()
                    ? 'bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white shadow-lg shadow-emerald-500/25 hover:scale-[1.02]'
                    : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                }`}
              >
                ➕ {t('owners.addOwner')}
              </Link>
              <Link
                to={currentUserIsOwner() ? "/new-transaction?action=change-threshold" : "#"}
                onClick={(e) => {
                  if (!currentUserIsOwner()) {
                    e.preventDefault()
                  }
                }}
                className={`flex-1 h-12 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${
                  currentUserIsOwner()
                    ? 'bg-gradient-to-r from-blue-500 to-indigo-500 hover:from-blue-400 hover:to-indigo-400 text-white shadow-lg shadow-blue-500/25 hover:scale-[1.02]'
                    : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                }`}
              >
                ⚙️ {t('owners.changeThreshold')}
              </Link>
            </div>
          </div>

          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
            <h3 className="font-bold text-gray-900 text-lg mb-6">{t('owners.ownersList')}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {safeInfo.owners.map((owner, idx) => {
                const you = isOwner(owner)
                const explorerUrl = effectiveChainId ? getExplorerAddressUrl(effectiveChainId, owner) : '#'

                return (
                  <div
                    key={owner}
                    className={`p-4 rounded-2xl border transition-all ${
                      you
                        ? 'bg-gradient-to-br from-primary-50 to-primary-100 border-primary-300 shadow-md shadow-primary-500/10'
                        : 'bg-gray-50 border-gray-200 hover:border-gray-300 hover:shadow-sm'
                    }`}
                  >
                    <div className="flex items-start gap-3 mb-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-sm font-bold flex-shrink-0 ${
                        you ? 'bg-primary-500 text-white' : 'bg-gray-200 text-gray-600'
                      }`}>
                        {idx + 1}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          {you && (
                            <span className="px-2 py-0.5 bg-primary-500 text-white text-xs font-bold rounded-lg">
                              {t('owners.you')}
                            </span>
                          )}
                        </div>
                        <div className="font-mono text-sm text-gray-800 break-all">
                          {shortenAddress(owner, 8)}
                        </div>
                      </div>
                    </div>

                    <div className="flex gap-2 flex-wrap">
                      <button
                        onClick={() => handleCopy(owner)}
                        className="flex-1 min-w-[80px] h-9 px-3 rounded-lg bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 hover:border-gray-300 font-semibold text-xs transition-colors flex items-center justify-center gap-1"
                      >
                        {copiedAddress === owner ? (
                          <>✓ {t('common.copied')}</>
                        ) : (
                          <>📋 {t('common.copy')}</>
                        )}
                      </button>
                      <a
                        href={explorerUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex-1 min-w-[80px] h-9 px-3 rounded-lg bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 hover:border-gray-300 font-semibold text-xs transition-colors flex items-center justify-center gap-1"
                      >
                        🔍 {t('common.viewOnExplorer')}
                      </a>
                      {currentUserIsOwner() && safeInfo.owners.length > 1 && !you && (
                        <Link
                          to={`/new-transaction?action=remove-owner&address=${owner}`}
                          className="flex-1 min-w-[80px] h-9 px-3 rounded-lg bg-red-50 border border-red-200 text-red-600 hover:bg-red-100 hover:border-red-300 font-semibold text-xs transition-colors flex items-center justify-center gap-1"
                        >
                          🗑️ {t('owners.remove')}
                        </Link>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </>
      ) : null}
    </div>
  )
}

export default Owners

