import { useEffect, useState, useCallback } from 'react'
import { Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { ethers } from 'ethers'
import { useWalletStore, useMultisigStore } from '@/store/wallet'
import {
  getSafeServiceUrl,
  getSafePendingTxs,
  getSafeExecutedTxs,
  getSafeWebUrl,
  signTransactionHash,
  buildSignatures,
  getSafeInfo
} from '@/utils/safe'
import { SAFE_ABI, SUPPORTED_CHAINS } from '@/config'
import { shortenAddress, getExplorerTxUrl } from '@/utils/address'
import { getChainIconUrl } from '@/utils/chains'
import type { SafePendingTx, SafeInfo } from '@/utils/safe'

type TxType = 'transfer' | 'addOwner' | 'removeOwner' | 'changeThreshold' | 'transferOwnership' | 'erc20Transfer' | 'custom'
interface DecodedTx {
  type: TxType
  description: string
}

function Transactions() {
  const { t } = useTranslation()
  const { provider, signer, chainId: walletChainId, account } = useWalletStore()
  const { currentMultisig } = useMultisigStore()

  const [safeAddress, setSafeAddress] = useState<string | null>(null)
  const [safeInfo, setSafeInfo] = useState<SafeInfo | null>(null)
  const [pendingTxs, setPendingTxs] = useState<SafePendingTx[]>([])
  const [executedTxs, setExecutedTxs] = useState<SafePendingTx[]>([])
  type TxTab = 'needsSign' | 'signedByMe' | 'readyToExecute' | 'executed'
  const [activeTab, setActiveTab] = useState<TxTab>('needsSign')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [signingTx, setSigningTx] = useState<string | null>(null)
  const [executingTx, setExecutingTx] = useState<string | null>(null)
  const [txError, setTxError] = useState<string | null>(null)

  const decodeTransactionData = useCallback((data: string | null, value: string): DecodedTx => {
    if (!data || data === '0x' || data === '') {
      const ethValue = ethers.utils.formatEther(value || '0')
      return {
        type: 'transfer',
        description: t('txs.transferEth', { amount: ethValue })
      }
    }

    try {
      const addOwnerIface = new ethers.utils.Interface(['function addOwnerWithThreshold(address owner, uint256 _threshold)'])
      const removeOwnerIface = new ethers.utils.Interface(['function removeOwner(address prevOwner, address owner, uint256 _threshold)'])
      const changeThresholdIface = new ethers.utils.Interface(['function changeThreshold(uint256 _threshold)'])
      const transferOwnershipIface = new ethers.utils.Interface(['function transferOwnership(address newOwner)'])
      const erc20TransferIface = new ethers.utils.Interface(['function transfer(address to, uint256 value)'])

      try {
        const decoded = addOwnerIface.parseTransaction({ data })
        return {
          type: 'addOwner',
          description: t('txs.descAddOwner', { address: shortenAddress(decoded.args.owner) })
        }
      } catch {}

      try {
        const decoded = removeOwnerIface.parseTransaction({ data })
        return {
          type: 'removeOwner',
          description: t('txs.descRemoveOwner', { address: shortenAddress(decoded.args.owner) })
        }
      } catch {}

      try {
        const decoded = changeThresholdIface.parseTransaction({ data })
        return {
          type: 'changeThreshold',
          description: t('txs.descChangeThreshold', { threshold: decoded.args._threshold.toString() })
        }
      } catch {}

      try {
        const decoded = transferOwnershipIface.parseTransaction({ data })
        return {
          type: 'transferOwnership',
          description: t('txs.descTransferOwnership', { address: shortenAddress(decoded.args.newOwner) })
        }
      } catch {}

      try {
        const decoded = erc20TransferIface.parseTransaction({ data })
        return {
          type: 'transfer',
          description: t('txs.descErc20Transfer', { address: shortenAddress(decoded.args.to) })
        }
      } catch {}

      return {
        type: 'custom',
        description: `${data.slice(0, 10)}...`
      }
    } catch {
      return {
        type: 'custom',
        description: `${data.slice(0, 10)}...`
      }
    }
  }, [t])

  useEffect(() => {
    if (currentMultisig && ethers.utils.isAddress(currentMultisig)) {
      setSafeAddress(currentMultisig.toLowerCase())
    } else {
      setSafeAddress(null)
    }
  }, [currentMultisig])

  const effectiveChainId = safeInfo?.chainId || walletChainId
  const currentChain = effectiveChainId ? SUPPORTED_CHAINS[effectiveChainId] : null
  const hasService = currentChain ? !!getSafeServiceUrl(currentChain.chainId) : false
  const safeWebUrl = currentChain && safeAddress ? getSafeWebUrl(currentChain.chainId, safeAddress) : null

  const loadSafeInfo = useCallback(async () => {
    if (!provider || !safeAddress) return
    try {
      const info = await getSafeInfo(provider, safeAddress)
      setSafeInfo(info)
      return info
    } catch (e) {
      console.error('Failed to load safe info:', e)
      return null
    }
  }, [provider, safeAddress])

  const loadTransactions = useCallback(async () => {
    if (!safeAddress) return
    const chainId = safeInfo?.chainId || walletChainId
    if (!chainId) return
    const serviceUrl = getSafeServiceUrl(chainId)
    if (!serviceUrl) {
      setPendingTxs([])
      setExecutedTxs([])
      return
    }

    try {
      const [pending, executed] = await Promise.all([
        getSafePendingTxs(chainId, safeAddress),
        getSafeExecutedTxs(chainId, safeAddress)
      ])
      setPendingTxs(pending)
      setExecutedTxs(executed)
    } catch (e) {
      console.error('Failed to load transactions:', e)
      setError(t('txs.errorLoading'))
    }
  }, [safeAddress, safeInfo?.chainId, walletChainId, t])

  const loadAllData = useCallback(async () => {
    if (!safeAddress || !provider) {
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    setTxError(null)
    try {
      await loadSafeInfo()
      await loadTransactions()
    } catch (e: any) {
      console.error('Failed to load data:', e)
      setError(t('txs.errorLoading'))
    } finally {
      setLoading(false)
    }
  }, [safeAddress, provider, loadSafeInfo, loadTransactions, t])

  useEffect(() => {
    loadAllData()
  }, [loadAllData])

  useEffect(() => {
    if (!safeAddress || !hasService) return
    const interval = setInterval(() => {
      loadTransactions()
    }, 15000)
    return () => clearInterval(interval)
  }, [safeAddress, hasService, loadTransactions])

  const handleSign = async (tx: SafePendingTx) => {
    if (!signer || !account || !safeAddress || !effectiveChainId) return
    setSigningTx(tx.safeTxHash || `${tx.nonce}-${tx.to}`)
    setTxError(null)
    try {
      // 签名前再次检查是否是持有人
      if (!isOwner(account)) {
        throw new Error(t('txs.notOwnerWarning', { connected: shortenAddress(account) }))
      }

      // 签名前先刷新一次交易列表，获取最新状态，避免对已执行/已达阈值的交易签名
      await loadTransactions()

      // 刷新后重新查找这笔交易的最新状态
      const latestPendingTxs = await getSafePendingTxs(effectiveChainId, safeAddress)
      const latestTx = latestPendingTxs.find(t => 
        (tx.safeTxHash && t.safeTxHash === tx.safeTxHash) || 
        (t.nonce === tx.nonce && t.to.toLowerCase() === tx.to.toLowerCase())
      )

      if (!latestTx) {
        // 交易不在待处理列表中，可能已经执行
        setTimeout(() => loadTransactions(), 500)
        throw new Error(t('txs.txAlreadyExecuted'))
      }

      if (latestTx.isExecuted) {
        setTimeout(() => loadTransactions(), 500)
        throw new Error(t('txs.txAlreadyExecuted'))
      }

      const threshold = safeInfo?.threshold || 1
      if (latestTx.confirmations.length >= threshold) {
        // 已经达到执行阈值，不需要再签名了
        setTimeout(() => loadTransactions(), 500)
        throw new Error(t('txs.txAlreadyExecuted'))
      }

      if (latestTx.confirmations.some(c => c.owner.toLowerCase() === account.toLowerCase())) {
        // 你已经签过名了
        setTimeout(() => loadTransactions(), 500)
        throw new Error(t('txs.alreadySigned'))
      }

      const safeTxHash = latestTx.safeTxHash || await getSafeTxHash(latestTx)
      const txData = {
        to: ethers.utils.getAddress(latestTx.to),
        value: ethers.BigNumber.from(latestTx.value || 0),
        data: latestTx.data || '0x',
        operation: Number(latestTx.operation),
        safeTxGas: ethers.BigNumber.from(latestTx.safeTxGas || 0),
        baseGas: ethers.BigNumber.from(latestTx.baseGas || 0),
        gasPrice: ethers.BigNumber.from(latestTx.gasPrice || 0),
        gasToken: latestTx.gasToken && latestTx.gasToken !== ethers.constants.AddressZero ? ethers.utils.getAddress(latestTx.gasToken) : ethers.constants.AddressZero,
        refundReceiver: latestTx.refundReceiver && latestTx.refundReceiver !== ethers.constants.AddressZero ? ethers.utils.getAddress(latestTx.refundReceiver) : ethers.constants.AddressZero,
        nonce: Number(latestTx.nonce)
      }
      const signResult = await signTransactionHash(signer, effectiveChainId, safeAddress, txData)
      const signature = signResult.signature

      // 验证签名恢复地址和hash匹配
      if (signResult.recoveredAddress.toLowerCase() !== account.toLowerCase()) {
        throw new Error(t('txs.sigVerifyFailed'))
      }
      if (signResult.txHash.toLowerCase() !== safeTxHash.toLowerCase()) {
        console.error('Hash mismatch! Local:', signResult.txHash, 'API:', safeTxHash)
        throw new Error(t('txs.hashMismatch'))
      }

      const serviceUrl = getSafeServiceUrl(effectiveChainId)
      if (!serviceUrl) throw new Error('No service URL')
      const checksumSafe = ethers.utils.getAddress(safeAddress)
      const res = await fetch(`${serviceUrl}/api/v1/safes/${checksumSafe}/multisig-transactions/${safeTxHash}/confirmations/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ signature })
      })
      if (!res.ok) {
        const errText = await res.text()
        if (res.status === 404) {
          // 交易已执行或不存在，自动刷新
          setTimeout(() => loadTransactions(), 500)
          setTimeout(() => loadTransactions(), 2000)
          throw new Error(t('txs.txAlreadyExecuted'))
        }
        let errMsg = `Failed to submit confirmation (HTTP ${res.status})`
        try {
          const errData = JSON.parse(errText)
          if (errData.nonFieldErrors) {
            const rawErr = errData.nonFieldErrors.join(', ')
            // 识别"不是持有人"错误，给出友好提示
            if (rawErr.includes('is not an owner or delegate')) {
              errMsg = t('txs.apiNotOwnerError', { connected: shortenAddress(account) })
            } else {
              errMsg = rawErr
            }
          }
          else if (errData.detail) errMsg = errData.detail
          else errMsg = errText
        } catch {}
        console.error('Submit confirmation error response:', errText)
        throw new Error(errMsg)
      }
      await loadTransactions()
      setTimeout(() => loadTransactions(), 2000)
      setTimeout(() => loadTransactions(), 5000)
    } catch (e: any) {
      console.error('Sign failed:', e)
      setTxError(e.message || t('txs.signFailed'))
    } finally {
      setSigningTx(null)
    }
  }

  const getSafeTxHash = async (tx: SafePendingTx): Promise<string> => {
    if (tx.safeTxHash) return tx.safeTxHash
    if (!provider || !safeAddress) throw new Error('No provider or safe address')
    const contract = new ethers.Contract(safeAddress, SAFE_ABI, provider)
    return contract.getTransactionHash(
      ethers.utils.getAddress(tx.to),
      ethers.BigNumber.from(tx.value || 0),
      tx.data || '0x',
      Number(tx.operation),
      ethers.BigNumber.from(tx.safeTxGas || 0),
      ethers.BigNumber.from(tx.baseGas || 0),
      ethers.BigNumber.from(tx.gasPrice || 0),
      tx.gasToken && tx.gasToken !== ethers.constants.AddressZero ? ethers.utils.getAddress(tx.gasToken) : ethers.constants.AddressZero,
      tx.refundReceiver && tx.refundReceiver !== ethers.constants.AddressZero ? ethers.utils.getAddress(tx.refundReceiver) : ethers.constants.AddressZero,
      Number(tx.nonce)
    )
  }

  const handleExecute = async (tx: SafePendingTx) => {
    if (!signer || !safeAddress || !effectiveChainId) return
    setExecutingTx(tx.safeTxHash || `${tx.nonce}-${tx.to}`)
    setTxError(null)
    try {
      const sigMap: Record<string, string> = {}
      tx.confirmations.forEach(conf => {
        if (conf.signature) {
          sigMap[conf.owner.toLowerCase()] = conf.signature
        }
      })
      const signatures = buildSignatures(sigMap)
      const contract = new ethers.Contract(safeAddress, SAFE_ABI, signer)
      const txResponse = await contract.execTransaction(
        ethers.utils.getAddress(tx.to),
        ethers.BigNumber.from(tx.value || 0),
        tx.data || '0x',
        Number(tx.operation),
        ethers.BigNumber.from(tx.safeTxGas || 0),
        ethers.BigNumber.from(tx.baseGas || 0),
        ethers.BigNumber.from(tx.gasPrice || 0),
        tx.gasToken && tx.gasToken !== ethers.constants.AddressZero ? ethers.utils.getAddress(tx.gasToken) : ethers.constants.AddressZero,
        tx.refundReceiver && tx.refundReceiver !== ethers.constants.AddressZero ? ethers.utils.getAddress(tx.refundReceiver) : ethers.constants.AddressZero,
        signatures,
        {
          value: ethers.BigNumber.from(tx.value || 0),
          gasLimit: ethers.BigNumber.from('500000')
        }
      )
      await txResponse.wait()
      await loadTransactions()
      setTimeout(() => loadTransactions(), 3000)
      setTimeout(() => loadTransactions(), 8000)
    } catch (e: any) {
      console.error('Execute failed:', e)
      setTxError(e.message || t('txs.executeFailed'))
    } finally {
      setExecutingTx(null)
    }
  }

  const formatDate = (dateStr: string): string => {
    try {
      return new Date(dateStr).toLocaleString()
    } catch {
      return dateStr
    }
  }

  const isOwner = (ownerAddr: string): boolean => {
    if (!safeInfo?.owners) return false
    return safeInfo.owners.some(o => o.toLowerCase() === ownerAddr.toLowerCase())
  }

  const hasSigned = (tx: SafePendingTx, ownerAddr: string): boolean => {
    return tx.confirmations.some(c => c.owner.toLowerCase() === ownerAddr.toLowerCase())
  }

  const canExecute = (tx: SafePendingTx): boolean => {
    if (tx.isExecuted) return false
    const threshold = safeInfo?.threshold || 0
    return tx.confirmations.length >= threshold
  }

  const canSign = (tx: SafePendingTx): boolean => {
    if (!account || !isOwner(account)) return false
    if (tx.isExecuted) return false
    if (canExecute(tx)) return false // 已经满足执行阈值，不再显示签名按钮，直接执行即可
    return !hasSigned(tx, account)
  }

  // 四个列表的真实数据过滤
  const needsSignTxs = pendingTxs.filter(tx => {
    if (tx.isExecuted) return false
    if (canExecute(tx)) return false
    if (!account || !isOwner(account)) return false
    return !hasSigned(tx, account)
  })

  const signedByMeTxs = pendingTxs.filter(tx => {
    if (tx.isExecuted) return false
    if (canExecute(tx)) return false
    if (!account || !isOwner(account)) return false
    return hasSigned(tx, account)
  })

  const readyToExecuteTxs = pendingTxs.filter(tx => {
    if (tx.isExecuted) return false
    return canExecute(tx)
  })

  const getTxTypeLabel = (type: TxType): string => {
    const labels: Record<TxType, string> = {
      transfer: t('txs.typeTransfer'),
      addOwner: t('txs.typeAddOwner'),
      removeOwner: t('txs.typeRemoveOwner'),
      changeThreshold: t('txs.typeChangeThreshold'),
      transferOwnership: t('txs.typeTransferOwnership'),
      erc20Transfer: t('txs.typeErc20Transfer'),
      custom: t('txs.typeCustom')
    }
    return labels[type]
  }

  const getTxTypeColor = (type: TxType): string => {
    const colors: Record<TxType, string> = {
      transfer: 'bg-emerald-100 text-emerald-700',
      addOwner: 'bg-blue-100 text-blue-700',
      removeOwner: 'bg-red-100 text-red-700',
      changeThreshold: 'bg-amber-100 text-amber-700',
      transferOwnership: 'bg-red-100 text-red-700',
      erc20Transfer: 'bg-teal-100 text-teal-700',
      custom: 'bg-gray-100 text-gray-700'
    }
    return colors[type]
  }

  if (!safeAddress) {
    return (
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8 sm:p-12 text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-gray-100 text-gray-400 text-4xl flex items-center justify-center">
          🔍
        </div>
        <h2 className="text-xl font-bold text-gray-900 mb-3">{t('txs.noMultisig')}</h2>
        <p className="text-gray-500 mb-8">{t('txs.noMultisigDesc')}</p>
        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <Link
            to="/"
            className="bg-white border-2 border-gray-200 hover:border-primary-300 hover:bg-primary-50 text-gray-700 font-bold px-6 py-3 rounded-xl transition-colors"
          >
            {t('common.backHome')}
          </Link>
          <Link
            to="/import"
            className="bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold px-6 py-3 rounded-xl shadow-lg shadow-primary-500/25 transition-transform hover:scale-105"
          >
            {t('txs.goImport')}
          </Link>
        </div>
      </div>
    )
  }

  const tabs: { key: TxTab; label: string; count: number; icon: string }[] = [
    { key: 'needsSign', label: t('txs.tabNeedsSign'), count: needsSignTxs.length, icon: '✍️' },
    { key: 'signedByMe', label: t('txs.tabSignedByMe'), count: signedByMeTxs.length, icon: '✅' },
    { key: 'readyToExecute', label: t('txs.tabReadyToExecute'), count: readyToExecuteTxs.length, icon: '🚀' },
    { key: 'executed', label: t('txs.tabExecuted'), count: executedTxs.length, icon: '📜' },
  ]

  const getDisplayTxs = (): SafePendingTx[] => {
    switch (activeTab) {
      case 'needsSign': return needsSignTxs
      case 'signedByMe': return signedByMeTxs
      case 'readyToExecute': return readyToExecuteTxs
      case 'executed': return executedTxs
      default: return []
    }
  }

  const getEmptyText = (): string => {
    switch (activeTab) {
      case 'needsSign': return t('txs.noNeedsSign')
      case 'signedByMe': return t('txs.noSignedByMe')
      case 'readyToExecute': return t('txs.noReadyToExecute')
      case 'executed': return t('txs.noExecuted')
      default: return ''
    }
  }

  const displayTxs = getDisplayTxs()
  const emptyText = getEmptyText()

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-4 sm:p-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <Link to={`/dashboard/${safeAddress}`} className="text-sm text-primary-600 hover:text-primary-700 font-semibold mb-2 inline-block">
              ← {t('common.backToDashboard')}
            </Link>
            <h2 className="text-xl sm:text-2xl font-bold text-gray-900">{t('txs.title')}</h2>
          </div>
          <button
            onClick={loadAllData}
            disabled={loading}
            className="h-10 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            <span className={loading ? 'animate-spin' : ''}>🔄</span>
            {t('txs.refresh')}
          </button>
        </div>

        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 p-4 bg-gradient-to-br from-gray-50 to-gray-100 rounded-xl border border-gray-200 mb-6 flex-wrap">
          {currentChain && (
            <img
              src={getChainIconUrl(currentChain.chainId)}
              alt={currentChain.shortName}
              className="w-12 h-12 rounded-full object-contain bg-white p-1.5 border border-gray-200 flex-shrink-0"
              onError={(e) => { (e.target as HTMLImageElement).style.display = 'none' }}
            />
          )}
          <div className="min-w-0 flex-1">
            <div className="font-mono text-sm sm:text-lg text-gray-800 break-all mb-1">{safeAddress}</div>
            <div className="flex items-center gap-3 flex-wrap">
              {currentChain && (
                <span className="text-xs sm:text-sm text-gray-500 flex items-center gap-1">
                  {t('txs.currentChain')}: <strong className="text-gray-700">{currentChain.name}</strong>
                  {currentChain.isTestnet && (
                    <span className="ml-1 px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded text-xs font-semibold">
                      {t('txs.testnet')}
                    </span>
                  )}
                </span>
              )}
            </div>
          </div>
          {safeWebUrl && (
            <a
              href={`${safeWebUrl}/transactions`}
              target="_blank"
              rel="noopener noreferrer"
              className="h-10 px-4 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-sm transition-colors flex items-center justify-center flex-shrink-0"
            >
              🔗 {t('txs.openOfficial')}
            </a>
          )}
        </div>

        {/* 当前钱包身份提示 */}
        {account && (
          <div className={`mb-6 p-4 rounded-xl border ${
            isOwner(account) 
              ? 'bg-emerald-50 border-emerald-200' 
              : 'bg-red-50 border-red-200'
          }`}>
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-lg">{isOwner(account) ? '✅' : '⚠️'}</span>
              <span className={`text-sm font-semibold ${
                isOwner(account) ? 'text-emerald-800' : 'text-red-800'
              }`}>
                {isOwner(account) 
                  ? t('txs.currentIsOwner', { address: shortenAddress(account) })
                  : t('txs.currentNotOwner', { address: shortenAddress(account) })
                }
              </span>
            </div>
            {!isOwner(account) && safeInfo && (
              <p className="text-xs text-red-700 mt-2 pl-7">
                {t('txs.currentNotOwnerHint')}
              </p>
            )}
          </div>
        )}

        {!hasService && (
          <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 sm:p-6 mb-6">
            <h3 className="font-bold text-amber-800 mb-2">⚠️ {t('txs.noServiceTitle')}</h3>
            <p className="text-sm text-amber-700 mb-4">
              {t('txs.noServiceDesc')}
            </p>
            {safeWebUrl && (
              <a
                href={`${safeWebUrl}/transactions`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-amber-600 hover:bg-amber-700 text-white font-semibold text-sm transition-colors"
              >
                🔗 {t('txs.viewOnOfficial')}
              </a>
            )}
          </div>
        )}

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-2xl p-4 sm:p-6 mb-6">
            <p className="text-red-700 font-semibold mb-2">⚠️ {error}</p>
            <button
              onClick={loadAllData}
              className="text-sm text-red-600 hover:text-red-700 font-semibold underline"
            >
              {t('txs.refresh')}
            </button>
          </div>
        )}

        {txError && (
          <div className="bg-red-50 border border-red-200 rounded-2xl p-4 mb-6">
            <p className="text-red-700 text-sm">{txError}</p>
          </div>
        )}

        <div className="flex gap-1 mb-6 border-b border-gray-200 overflow-x-auto pb-px">
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`px-3 sm:px-4 py-3 font-semibold text-xs sm:text-sm transition-colors relative whitespace-nowrap flex items-center gap-1.5 ${
                activeTab === tab.key
                  ? 'text-primary-600'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <span>{tab.icon}</span>
              <span>{tab.label}</span>
              {tab.count > 0 && (
                <span className={`px-1.5 py-0.5 text-white text-xs font-bold rounded-full ${
                  activeTab === tab.key ? 'bg-primary-500' : 'bg-gray-400'
                }`}>
                  {tab.count}
                </span>
              )}
              {activeTab === tab.key && (
                <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary-500" />
              )}
            </button>
          ))}
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="text-gray-400 flex items-center gap-2">
              <span className="animate-spin">⏳</span>
              {t('txs.loading')}
            </div>
          </div>
        ) : displayTxs.length === 0 ? (
          <div className="py-12 text-center">
            <div className="w-16 h-16 mx-auto mb-4 rounded-2xl bg-gray-100 text-gray-400 text-3xl flex items-center justify-center">
              {tabs.find(t => t.key === activeTab)?.icon || '📭'}
            </div>
            <p className="text-gray-500 font-medium">
              {emptyText}
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {displayTxs.map((tx) => {
              const decoded = decodeTransactionData(tx.data, tx.value)
              const threshold = safeInfo?.threshold || 0
              const confirmCount = tx.confirmations.length
              const isSigned = account ? hasSigned(tx, account) : false
              const isSigning = signingTx === (tx.safeTxHash || `${tx.nonce}-${tx.to}`)
              const isExecuting = executingTx === (tx.safeTxHash || `${tx.nonce}-${tx.to}`)
              const explorerUrl = currentChain && tx.txHash
                ? getExplorerTxUrl(currentChain.chainId, tx.txHash)
                : null

              return (
                <div
                  key={tx.safeTxHash || `${tx.nonce}-${tx.to}-${tx.submissionDate}`}
                  className="p-4 sm:p-5 rounded-2xl border border-gray-200 bg-gray-50/50 hover:bg-white hover:shadow-md transition-all"
                >
                  <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3 mb-4">
                    <div className="flex items-center gap-3 flex-wrap">
                      <span className="px-3 py-1 bg-gray-200 text-gray-700 rounded-lg text-sm font-bold">
                        #{tx.nonce}
                      </span>
                      <span className={`px-3 py-1 rounded-lg text-sm font-semibold ${getTxTypeColor(decoded.type)}`}>
                        {getTxTypeLabel(decoded.type)}
                      </span>
                      {tx.isExecuted && (
                        <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-sm font-semibold">
                          ✓ {t('txs.executed')}
                        </span>
                      )}
                    </div>
                    <div className="text-xs text-gray-400">
                      {formatDate(tx.submissionDate)}
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
                    <div className="p-3 rounded-xl bg-white border border-gray-200">
                      <div className="text-xs text-gray-500 font-semibold mb-1">{t('txs.to')}</div>
                      <div className="font-mono text-sm text-gray-800 break-all">
                        {shortenAddress(tx.to)}
                      </div>
                    </div>
                    <div className="p-3 rounded-xl bg-white border border-gray-200">
                      <div className="text-xs text-gray-500 font-semibold mb-1">{t('txs.value')}</div>
                      <div className="text-sm text-gray-800 font-medium">
                        {decoded.description}
                      </div>
                    </div>
                  </div>

                  <div className="p-3 rounded-xl bg-white border border-gray-200 mb-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="text-xs text-gray-500 font-semibold">
                        {t('txs.confirmations')}
                      </div>
                      <div className="text-sm font-bold">
                        <span className={confirmCount >= threshold ? 'text-emerald-600' : 'text-amber-600'}>
                          {confirmCount}
                        </span>
                        <span className="text-gray-400"> / {threshold}</span>
                      </div>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2 mb-3">
                      <div
                        className={`h-2 rounded-full transition-all ${
                          confirmCount >= threshold ? 'bg-emerald-500' : 'bg-amber-500'
                        }`}
                        style={{ width: `${Math.min((confirmCount / Math.max(threshold, 1)) * 100, 100)}%` }}
                      />
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {tx.confirmations.map((conf, idx) => {
                        const isYou = account && conf.owner.toLowerCase() === account.toLowerCase()
                        return (
                          <span
                            key={`${conf.owner}-${idx}`}
                            className={`inline-flex items-center gap-1 px-2 py-1 rounded-lg text-xs font-semibold ${
                              isYou
                                ? 'bg-primary-100 text-primary-700'
                                : 'bg-gray-100 text-gray-600'
                            }`}
                          >
                            ✓ {shortenAddress(conf.owner, 4)}
                            {isYou && <span className="text-primary-500">({t('txs.you')})</span>}
                          </span>
                        )
                      })}
                    </div>
                  </div>

                  {tx.isExecuted && tx.txHash && (
                    <div className="p-3 rounded-xl bg-emerald-50 border border-emerald-200 mb-4">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-emerald-600 font-semibold text-sm">✓ {t('txs.executedAt')}</span>
                        <span className="text-xs text-emerald-600">{tx.executionDate ? formatDate(tx.executionDate) : ''}</span>
                      </div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-mono text-xs text-emerald-700 break-all">
                          {shortenAddress(tx.txHash)}
                        </span>
                        {explorerUrl && (
                          <a
                            href={explorerUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-xs text-emerald-600 hover:text-emerald-700 font-semibold underline"
                          >
                            {t('txs.viewOnExplorer')}
                          </a>
                        )}
                      </div>
                    </div>
                  )}

                  {!tx.isExecuted && (
                    <div className="flex flex-col sm:flex-row gap-2">
                      {canSign(tx) && (
                        <button
                          onClick={() => handleSign(tx)}
                          disabled={isSigning || isExecuting}
                          className="flex-1 h-11 px-4 rounded-xl bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-400 hover:to-primary-500 text-white font-bold text-sm transition-all shadow-lg shadow-primary-500/25 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                          {isSigning ? (
                            <>
                              <span className="animate-spin">⏳</span>
                              {t('txs.signing')}
                            </>
                          ) : (
                            <>
                              ✍️ {t('txs.sign')}
                            </>
                          )}
                        </button>
                      )}
                      {isSigned && !canExecute(tx) && (
                        <div className="flex-1 h-11 px-4 rounded-xl bg-emerald-50 text-emerald-700 font-bold text-sm flex items-center justify-center gap-2 border border-emerald-200">
                          ✓ {t('txs.alreadySigned')}
                        </div>
                      )}
                      {canExecute(tx) && (
                        <button
                          onClick={() => handleExecute(tx)}
                          disabled={isSigning || isExecuting}
                          className="flex-1 h-11 px-4 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white font-bold text-sm transition-all shadow-lg shadow-emerald-500/25 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                          {isExecuting ? (
                            <>
                              <span className="animate-spin">⏳</span>
                              {t('txs.executing')}
                            </>
                          ) : (
                            <>
                              🚀 {t('txs.execute')}
                            </>
                          )}
                        </button>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

export default Transactions

import { ethers } from 'ethers'
import { SAFE_ABI, SAFE_TX_TYPE, ERC20_ABI } from '@/config/abis'
import { SUPPORTED_CHAINS } from '@/config/chains'
import type { Web3Provider } from './chains'

export interface SafeTransactionData {
  to: string
  value: string
  data: string
  operation: number
  safeTxGas: string
  baseGas: string
  gasPrice: string
  gasToken: string
  refundReceiver: string
  nonce: number
}

export interface SafePendingTx {
  safe: string
  to: string
  value: string
  data: string | null
  operation: number
  safeTxGas: number
  baseGas: number
  gasPrice: string
  gasToken: string
  refundReceiver: string | null
  nonce: number
  submissionDate: string
  safeTxHash?: string
  confirmations: {
    owner: string
    submissionDate: string
    signature?: string
  }[]
  signatures?: string
  isExecuted: boolean
  txHash?: string
  executionDate?: string
}

export interface SafeInfo {
  address: string
  chainId: number
  owners: string[]
  threshold: number
  nonce: number
  balance: string
}

export interface TokenBalance {
  tokenAddress: string | null
  token: {
    name: string
    symbol: string
    decimals: number
    logoUri?: string
  } | null
  balance: string
}

export function getSafeServiceUrl(chainId: number): string | null {
  const chain = SUPPORTED_CHAINS[chainId]
  return chain?.safeTransactionService || null
}

export function getSafeWebUrl(chainId: number, address: string): string {
  const chain = SUPPORTED_CHAINS[chainId]
  if (!chain) return `https://app.safe.global/home?safe=${address}`
  return `https://app.safe.global/${chain.safeUrlPrefix}:${address}`
}

export async function getSafeInfo(provider: Web3Provider, safeAddress: string): Promise<SafeInfo> {
  const contract = new ethers.Contract(safeAddress, SAFE_ABI, provider)
  const network = await provider.getNetwork()
  const chainId = network.chainId
  const [owners, threshold, nonce, balance] = await Promise.all([
    contract.getOwners(),
    contract.getThreshold(),
    contract.nonce(),
    provider.getBalance(safeAddress)
  ])

  return {
    address: safeAddress,
    chainId,
    owners,
    threshold: threshold.toNumber(),
    nonce: nonce.toNumber(),
    balance: balance.toString()
  }
}

export async function getSafePendingTxs(chainId: number, safeAddress: string): Promise<SafePendingTx[]> {
  const serviceUrl = getSafeServiceUrl(chainId)
  if (!serviceUrl) return []

  try {
    const checksumAddr = ethers.utils.getAddress(safeAddress)
    const res = await fetch(
      `${serviceUrl}/api/v1/safes/${checksumAddr}/multisig-transactions/?executed=false&ordering=-nonce`
    )
    if (!res.ok) return []
    const data = await res.json()
    return data.results || []
  } catch (e) {
    console.error('Failed to fetch pending txs:', e)
    return []
  }
}

export async function getSafeExecutedTxs(chainId: number, safeAddress: string): Promise<SafePendingTx[]> {
  const serviceUrl = getSafeServiceUrl(chainId)
  if (!serviceUrl) return []

  try {
    const checksumAddr = ethers.utils.getAddress(safeAddress)
    const res = await fetch(
      `${serviceUrl}/api/v1/safes/${checksumAddr}/multisig-transactions/?executed=true&ordering=-nonce`
    )
    if (!res.ok) return []
    const data = await res.json()
    return data.results || []
  } catch (e) {
    console.error('Failed to fetch executed txs:', e)
    return []
  }
}

export async function getSafeTokenBalances(chainId: number, safeAddress: string): Promise<TokenBalance[]> {
  const serviceUrl = getSafeServiceUrl(chainId)
  if (!serviceUrl) return []

  try {
    const checksumAddr = ethers.utils.getAddress(safeAddress)
    const res = await fetch(`${serviceUrl}/api/v1/safes/${checksumAddr}/balances/?trusted=false&exclude_spam=true`)
    if (!res.ok) return []
    const data = await res.json()
    return data || []
  } catch (e) {
    console.error('Failed to fetch balances:', e)
    return []
  }
}

export function getTransactionHash(
  provider: Web3Provider,
  safeAddress: string,
  tx: Omit<SafeTransactionData, 'nonce'> & { nonce?: number }
): Promise<string> {
  const contract = new ethers.Contract(safeAddress, SAFE_ABI, provider)
  return contract.getTransactionHash(
    tx.to,
    tx.value,
    tx.data,
    tx.operation,
    tx.safeTxGas,
    tx.baseGas,
    tx.gasPrice,
    tx.gasToken,
    tx.refundReceiver,
    tx.nonce || 0
  )
}

export interface SafeTxInput {
  to: string
  value: string | number | ethers.BigNumber
  data: string
  operation: number
  safeTxGas: string | number | ethers.BigNumber
  baseGas: string | number | ethers.BigNumber
  gasPrice: string | number | ethers.BigNumber
  gasToken: string
  refundReceiver: string
  nonce?: number
}

export async function signTransactionHash(
  signer: ethers.Signer,
  chainId: number,
  safeAddress: string,
  txData: SafeTxInput
): Promise<{ signature: string; recoveredAddress: string; txHash: string; expectedSigner: string }> {
  const nonce = txData.nonce ?? 0
  const domain = {
    name: 'Safe',
    version: '1.3.0',
    chainId: chainId,
    verifyingContract: ethers.utils.getAddress(safeAddress)
  }
  // Safe 交易签名不包含 EIP712Domain 类型定义
  const types: Record<string, ethers.utils.TypedDataField[]> = {
    SafeTx: [...SAFE_TX_TYPE.SafeTx]
  }
  // 地址checksum逻辑与NewTransaction的toChecksum完全一致
  const toChecksum = (addr: string): string => {
    if (!addr || addr === ethers.constants.AddressZero) return ethers.constants.AddressZero
    return ethers.utils.getAddress(addr)
  }
  const value = {
    to: toChecksum(txData.to),
    value: ethers.BigNumber.from(txData.value || 0),
    data: txData.data || '0x',
    operation: Number(txData.operation),
    safeTxGas: ethers.BigNumber.from(txData.safeTxGas || 0),
    baseGas: ethers.BigNumber.from(txData.baseGas || 0),
    gasPrice: ethers.BigNumber.from(txData.gasPrice || 0),
    gasToken: toChecksum(txData.gasToken || ethers.constants.AddressZero),
    refundReceiver: toChecksum(txData.refundReceiver || ethers.constants.AddressZero),
    nonce: ethers.BigNumber.from(nonce)
  }
  const signTypedData = (
    signer as unknown as {
      _signTypedData(
        domain: ethers.utils.TypedDataDomain,
        types: Record<string, ethers.utils.TypedDataField[]>,
        value: Record<string, unknown>
      ): Promise<string>
    }
  )._signTypedData
  const signature = await signTypedData(domain, types, value)

  // 本地验证签名，确保恢复地址正确
  const recoveredAddress = ethers.utils.verifyTypedData(domain, types, value, signature)
  const expectedSigner = await signer.getAddress()

  return {
    signature,
    recoveredAddress,
    txHash: ethers.utils._TypedDataEncoder.hash(domain, types, value),
    expectedSigner
  }
}

export function buildEnableOwnerData(ownerAddress: string, threshold: number): string {
  const abi = ['function addOwnerWithThreshold(address owner, uint256 _threshold)']
  const iface = new ethers.utils.Interface(abi)
  return iface.encodeFunctionData('addOwnerWithThreshold', [ownerAddress, threshold])
}

export function buildDisableOwnerData(prevOwner: string, ownerAddress: string, threshold: number): string {
  const abi = ['function removeOwner(address prevOwner, address owner, uint256 _threshold)']
  const iface = new ethers.utils.Interface(abi)
  return iface.encodeFunctionData('removeOwner', [prevOwner, ownerAddress, threshold])
}

export function buildChangeThresholdData(threshold: number): string {
  const abi = ['function changeThreshold(uint256 _threshold)']
  const iface = new ethers.utils.Interface(abi)
  return iface.encodeFunctionData('changeThreshold', [threshold])
}

export function buildERC20TransferData(_tokenAddress: string, to: string, amount: string): string {
  const iface = new ethers.utils.Interface(ERC20_ABI)
  return iface.encodeFunctionData('transfer', [to, amount])
}

export function buildSignatures(signatures: Record<string, string>): string {
  const sortedOwners = Object.keys(signatures)
    .map(addr => addr.toLowerCase())
    .sort((a, b) => {
      // 地址按十六进制数值升序排序（小写字符串字典序和数值序一致）
      if (a < b) return -1
      if (a > b) return 1
      return 0
    })
  return '0x' + sortedOwners.map(addr => signatures[addr].slice(2)).join('')
}

export type DecodedSafeTxType = 'transfer' | 'addOwner' | 'removeOwner' | 'changeThreshold' | 'transferOwnership' | 'erc20Transfer' | 'custom'

export interface DecodedSafeTx {
  type: DecodedSafeTxType
  to?: string
  amount?: string
  newThreshold?: number
  owner?: string
  dataPreview: string
}

export function decodeSafeTransaction(data: string, value: string): DecodedSafeTx {
  try {
    if (!data || data === '0x') {
      return {
        type: 'transfer',
        amount: value,
        dataPreview: '0x'
      }
    }

    const addOwnerIface = new ethers.utils.Interface(['function addOwnerWithThreshold(address owner, uint256 _threshold)'])
    try {
      const decoded = addOwnerIface.parseTransaction({ data })
      return {
        type: 'addOwner',
        owner: decoded.args.owner,
        newThreshold: decoded.args._threshold.toNumber(),
        dataPreview: data.slice(0, 10) + '...'
      }
    } catch {
      /* 非该类型的交易数据，继续尝试下一种解码 */
    }

    const removeOwnerIface = new ethers.utils.Interface(['function removeOwner(address prevOwner, address owner, uint256 _threshold)'])
    try {
      const decoded = removeOwnerIface.parseTransaction({ data })
      return {
        type: 'removeOwner',
        owner: decoded.args.owner,
        newThreshold: decoded.args._threshold.toNumber(),
        dataPreview: data.slice(0, 10) + '...'
      }
    } catch {
      /* 非该类型的交易数据，继续尝试下一种解码 */
    }

    const changeThresholdIface = new ethers.utils.Interface(['function changeThreshold(uint256 _threshold)'])
    try {
      const decoded = changeThresholdIface.parseTransaction({ data })
      return {
        type: 'changeThreshold',
        newThreshold: decoded.args._threshold.toNumber(),
        dataPreview: data.slice(0, 10) + '...'
      }
    } catch {
      /* 非该类型的交易数据，继续尝试下一种解码 */
    }

    const transferOwnershipIface = new ethers.utils.Interface(['function transferOwnership(address newOwner)'])
    try {
      const decoded = transferOwnershipIface.parseTransaction({ data })
      return {
        type: 'transferOwnership',
        owner: decoded.args.newOwner,
        dataPreview: data.slice(0, 10) + '...'
      }
    } catch {
      /* 非该类型的交易数据，继续尝试下一种解码 */
    }

    const erc20Iface = new ethers.utils.Interface(ERC20_ABI)
    try {
      const decoded = erc20Iface.parseTransaction({ data })
      if (decoded.name === 'transfer') {
        return {
          type: 'erc20Transfer',
          to: decoded.args.to,
          amount: decoded.args.value.toString(),
          dataPreview: data.slice(0, 10) + '...'
        }
      }
    } catch {}

    return {
      type: 'custom',
      dataPreview: data.slice(0, 10) + '...'
    }
  } catch {
    return {
      type: 'custom',
      dataPreview: data.slice(0, 10) + '...'
    }
  }
}
